select ac_cargar_unidad($ac${"slug":"residuos-1","rama":"residuos","orden":1,"nivel":1,"titulo_es":"Qué pasa con lo que tirás","bajada_es":"La bolsa sale de tu casa, pero no desaparece. De qué está hecha, adónde va, qué le pasa y quién la recupera.","objetivos_es":["Definir qué es un residuo y cuánto genera una persona","Describir la composición típica de la basura de una casa","Seguir el recorrido de un residuo desde la casa hasta su destino final","Diferenciar un relleno sanitario de un basural a cielo abierto","Reconocer el trabajo de los recicladores urbanos en la gestión de residuos"],"repasa":["tronco-1","tronco-2"],"requiere_tronco":1,"fuentes":["ley-25916-residuos","ceamse","ley-1854-basura-cero","faccyr","epa"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"residuos-1.s1","orden":1,"tipo":"leccion","titulo_es":"La bolsa que sale de casa","bajada_es":"Qué es un residuo, cuánto genera cada persona y por qué \"tirar\" no es hacer desaparecer.","minutos":12,"pasos":[{"slug":"residuos-1.s1.p1","orden":1,"grupo":"residuos-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué es un residuo","cuerpo":["Un residuo es algo que su dueño descarta porque ya no le sirve. Los residuos sólidos urbanos (RSU) son los que se generan en casas, comercios, oficinas y la vía pública: restos de comida, envases, papeles, textiles, pequeños objetos rotos.","Hay otros residuos que tienen reglas propias, como los peligrosos (pilas, químicos, algunos aparatos electrónicos), los patogénicos (de hospitales) y los industriales."]},"solucion":{}},{"slug":"residuos-1.s1.p2","orden":2,"grupo":"residuos-1.s1.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un residuo sólido urbano o de otro tipo?","grupos":[{"id":"g1","nombre":"Residuo sólido urbano"},{"id":"g2","nombre":"Otro tipo (con reglas propias)"}],"items":[{"id":"i1","texto":"Cáscaras de papa"},{"id":"i2","texto":"Jeringas de un hospital"},{"id":"i3","texto":"Una caja de cartón"},{"id":"i4","texto":"Restos de solventes de una fábrica"},{"id":"i5","texto":"Una botella de plástico"},{"id":"i6","texto":"Pilas usadas"},{"id":"i7","texto":"Una remera rota"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2","i7":"g1"},"explicacion":"Los RSU son los de todos los días. Los otros necesitan una gestión especial porque pueden ser peligrosos."}},{"slug":"residuos-1.s1.p3","orden":3,"grupo":"residuos-1.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuánto tira una persona","cuerpo":["En Argentina, cada persona genera en promedio alrededor de 1 kilo de residuos por día, y bastante más en las grandes ciudades. Parece poco hasta que se multiplica: una familia de 4 genera unos 120 kilos por mes; una ciudad de un millón de habitantes, unas mil toneladas por día."],"destacado":{"valor":"≈ 1 kg","texto":"de residuos genera por día, en promedio, cada persona en Argentina."}},"solucion":{}},{"slug":"residuos-1.s1.p4","orden":4,"grupo":"residuos-1.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa viven 4 personas que generan 1 kg de residuos por día cada una. ¿Cuántos kilos generan en 30 días?","unidad":"kg","decimales":1},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"4 × 1 × 30 = 120 kg por mes. Lo que parece una bolsita por día es más que el peso de una persona por mes."}},{"slug":"residuos-1.s1.p4.v2","orden":4,"grupo":"residuos-1.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa viven 3 personas que generan 1,2 kg de residuos por día cada una. ¿Cuántos kilos generan en 30 días?","unidad":"kg","decimales":1},"solucion":{"valor":108,"tolerancia":2.16,"explicacion":"3 × 1,2 × 30 = 108 kg por mes. Lo que parece una bolsita por día es más que el peso de una persona por mes."}},{"slug":"residuos-1.s1.p4.v3","orden":4,"grupo":"residuos-1.s1.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa viven 5 personas que generan 0,9 kg de residuos por día cada una. ¿Cuántos kilos generan en 30 días?","unidad":"kg","decimales":1},"solucion":{"valor":135,"tolerancia":2.7,"explicacion":"5 × 0,9 × 30 = 135 kg por mes. Lo que parece una bolsita por día es más que el peso de una persona por mes."}},{"slug":"residuos-1.s1.p5","orden":5,"grupo":"residuos-1.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene 500.000 habitantes que generan 1 kg por día cada uno. ¿Cuántas toneladas genera por día?","unidad":"toneladas","decimales":0},"solucion":{"valor":500,"tolerancia":10,"explicacion":"500.000 kg ÷ 1.000 = 500 toneladas por día. Todos los días hay que recogerlas, transportarlas y hacer algo con ellas."}},{"slug":"residuos-1.s1.p5.v2","orden":5,"grupo":"residuos-1.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene 1.000.000 habitantes que generan 1 kg por día cada uno. ¿Cuántas toneladas genera por día?","unidad":"toneladas","decimales":0},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"1.000.000 kg ÷ 1.000 = 1.000 toneladas por día. Todos los días hay que recogerlas, transportarlas y hacer algo con ellas."}},{"slug":"residuos-1.s1.p5.v3","orden":5,"grupo":"residuos-1.s1.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad tiene 3.000.000 habitantes que generan 1 kg por día cada uno. ¿Cuántas toneladas genera por día?","unidad":"toneladas","decimales":0},"solucion":{"valor":3000,"tolerancia":60,"explicacion":"3.000.000 kg ÷ 1.000 = 3.000 toneladas por día. Todos los días hay que recogerlas, transportarlas y hacer algo con ellas."}},{"slug":"residuos-1.s1.p6","orden":6,"grupo":"residuos-1.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tirar es cambiar de lugar","cuerpo":["En el tronco viste que la materia no desaparece. Con la basura se ve claro: cuando la bolsa sale de casa, alguien la recoge, la transporta y la deja en otro lugar, donde se queda, se descompone o se recupera.","\"Afuera\" no existe. Cada residuo termina en algún lugar concreto, con consecuencias concretas para alguien."]},"solucion":{}},{"slug":"residuos-1.s1.p7","orden":7,"grupo":"residuos-1.s1.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Cuando el camión recolector se lleva la bolsa, el residuo deja de existir.","razones":[{"id":"r1","texto":"Porque la materia no desaparece: solo se traslada"},{"id":"r2","texto":"Porque el camión la destruye al compactarla"},{"id":"r3","texto":"Porque la basura se evapora en el relleno"}]},"solucion":{"valor":false,"explicacion":"Solo cambia de lugar. Termina en un relleno, un basural, una planta de reciclaje o, a veces, en un arroyo o un campo.","clave":["r1"]}},{"slug":"residuos-1.s1.p8","orden":8,"grupo":"residuos-1.s1.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido típico de una bolsa de basura en una ciudad.","items":[{"id":"i1","texto":"Se genera en la casa y se saca a la vereda"},{"id":"i2","texto":"El camión la recoge y la compacta"},{"id":"i3","texto":"Pasa por una estación de transferencia"},{"id":"i4","texto":"Llega a un relleno sanitario"},{"id":"i5","texto":"Se devuelve a la casa al mes siguiente"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuatro etapas típicas. La ley nacional de residuos domiciliarios las describe como gestión integral: de la generación a la disposición final."}},{"slug":"residuos-1.s1.p9","orden":9,"grupo":"residuos-1.s1.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las etapas de la gestión","cuerpo":["La Ley 25.916, de presupuestos mínimos para la gestión de residuos domiciliarios, describe las etapas de la gestión integral: generación, disposición inicial (cómo se saca a la calle), recolección y transporte, transferencia, tratamiento y disposición final.","Cada municipio organiza esas etapas. Por eso las reglas de cómo separar o qué día sacar la basura cambian de una ciudad a otra."]},"solucion":{}},{"slug":"residuos-1.s1.p10","orden":10,"grupo":"residuos-1.s1.p10","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas de la gestión de residuos según la ley.","items":[{"id":"i1","texto":"Generación"},{"id":"i2","texto":"Disposición inicial"},{"id":"i3","texto":"Recolección y transporte"},{"id":"i4","texto":"Transferencia"},{"id":"i5","texto":"Tratamiento"},{"id":"i6","texto":"Disposición final"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5","i6"],"explicacion":"Del tacho de la cocina al destino final. En cada etapa se puede reducir, separar o recuperar."}},{"slug":"residuos-1.s1.p11","orden":11,"grupo":"residuos-1.s1.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las reglas para separar la basura cambian de una ciudad a otra?","opciones":[{"id":"o1","texto":"Porque cada municipio organiza su propia gestión"},{"id":"o2","texto":"Porque los residuos son distintos en cada provincia"},{"id":"o3","texto":"Porque la ley nacional prohíbe separar"},{"id":"o4","texto":"Porque los camiones de cada ciudad son de otra marca"}]},"solucion":{"clave":["o1"],"explicacion":"La ley nacional fija un piso común; la recolección y el tratamiento son responsabilidad local.","por_opcion":{"o3":"La ley nacional fija mínimos; los municipios organizan los detalles."}}},{"slug":"residuos-1.s1.p12","orden":12,"grupo":"residuos-1.s1.p12","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué pasa con la basura de una ciudad cada día? Marcá todo lo correcto.","opciones":[{"id":"o1","texto":"Hay que recogerla"},{"id":"o2","texto":"Hay que transportarla"},{"id":"o3","texto":"Hay que decidir dónde termina"},{"id":"o4","texto":"Cuesta plata a todos los vecinos"},{"id":"o5","texto":"Se descompone sola en la vereda en unas horas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Recolectar y disponer residuos es uno de los mayores gastos de muchos municipios."}},{"slug":"residuos-1.s1.p13","orden":13,"grupo":"residuos-1.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Cada persona genera alrededor de {{0}} kilo de residuos por día; al tirarlos, la materia no {{1}}: cambia de {{2}}.","banco":[{"id":"w1","texto":"1"},{"id":"w2","texto":"desaparece"},{"id":"w3","texto":"lugar"},{"id":"w4","texto":"10"},{"id":"w5","texto":"aumenta"},{"id":"w6","texto":"forma"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La idea del tronco aplicada a la bolsa de basura."}},{"slug":"residuos-1.s1.p14","orden":14,"grupo":"residuos-1.s1.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Una persona genera cerca de un kilo de basura por día."},{"id":"s2","texto":"Una vez que el camión pasa, ya no es problema de nadie."},{"id":"s3","texto":"La gestión de residuos la organiza cada municipio."},{"id":"s4","texto":"Una familia no genera más de 10 kilos de basura por mes."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los números chicos por día se vuelven grandes por mes y por ciudad.","por_opcion":{"s2":"Termina en algún lugar, y el costo lo pagan todos: plata, espacio y contaminación.","s4":"Con 1 kg por persona por día, una familia de 4 genera unos 120 kg por mes."}}}]},{"slug":"residuos-1.s2","orden":2,"tipo":"leccion","titulo_es":"De qué está hecha la basura","bajada_es":"Orgánicos, papel, plásticos, vidrio y metales: la composición de la bolsa y por qué importa conocerla.","minutos":11,"pasos":[{"slug":"residuos-1.s2.p1","orden":1,"grupo":"residuos-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Abrir la bolsa","cuerpo":["Los estudios de composición de residuos abren y pesan muestras de bolsas reales para saber qué hay adentro. En las ciudades argentinas, lo que más pesa son los residuos orgánicos: restos de comida y de jardín, que suelen ser alrededor de la mitad.","Después vienen el papel y el cartón, los plásticos, el vidrio, los metales, los textiles y otros materiales como pañales, madera y escombros."],"datos":{"tipo":"barras","titulo":"Composición de los residuos de una ciudad argentina (ejemplo aproximado)","unidad":"% del peso","filas":[{"etiqueta":"Orgánicos","valor":45},{"etiqueta":"Plásticos","valor":15},{"etiqueta":"Papel y cartón","valor":14},{"etiqueta":"Pañales y sanitarios","valor":7},{"etiqueta":"Vidrio","valor":4},{"etiqueta":"Textiles","valor":4},{"etiqueta":"Metales","valor":2},{"etiqueta":"Otros","valor":9}],"nota":"Valores ilustrativos redondeados; varían según la ciudad, el barrio y la época del año."}},"solucion":{}},{"slug":"residuos-1.s2.p2","orden":2,"grupo":"residuos-1.s2.p2","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según ese ejemplo, ordená los materiales por su peso en la basura, de más a menos.","items":[{"id":"i1","texto":"Orgánicos"},{"id":"i2","texto":"Plásticos"},{"id":"i3","texto":"Papel y cartón"},{"id":"i4","texto":"Vidrio"},{"id":"i5","texto":"Metales"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los orgánicos son casi la mitad del peso. Cualquier plan serio de residuos tiene que empezar por ahí.","valores":{"i1":"≈ 45 %","i2":"≈ 15 %","i3":"≈ 14 %","i4":"≈ 4 %","i5":"≈ 2 %"}}},{"slug":"residuos-1.s2.p3","orden":3,"grupo":"residuos-1.s2.p3","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje del peso de la basura de una casa son restos orgánicos.","min":0,"max":100,"paso":5,"unidad":"%","escala":"lineal"},"solucion":{"valor":45,"banda":"lineal","explicacion":"Alrededor de la mitad. Por eso el compostaje, que vas a ver en esta rama, puede reducir tanto la basura."}},{"slug":"residuos-1.s2.p4","orden":4,"grupo":"residuos-1.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Peso contra volumen","cuerpo":["El peso y el volumen cuentan historias distintas. Los orgánicos pesan mucho porque tienen agua. Los plásticos y el cartón pesan poco pero ocupan mucho lugar: una bolsa llena de envases plásticos puede pesar menos de medio kilo.","Por eso un tacho puede llenarse rápido con envases sin que la basura pese mucho, y el volumen es lo que llena camiones y rellenos."]},"solucion":{}},{"slug":"residuos-1.s2.p5","orden":5,"grupo":"residuos-1.s2.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Como los plásticos pesan poco, casi no ocupan lugar en la basura.","razones":[{"id":"r1","texto":"Porque son livianos pero voluminosos"},{"id":"r2","texto":"Porque los plásticos se compactan hasta desaparecer"},{"id":"r3","texto":"Porque el peso y el volumen son siempre proporcionales"}]},"solucion":{"valor":false,"explicacion":"Pesan poco pero ocupan mucho volumen. Son una parte chica del peso y una parte grande del espacio.","clave":["r1"]}},{"slug":"residuos-1.s2.p6","orden":6,"grupo":"residuos-1.s2.p6","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué es más importante en este material: su peso o su volumen?","grupos":[{"id":"g1","nombre":"Pesa mucho (tiene agua)"},{"id":"g2","nombre":"Ocupa mucho (pesa poco)"}],"items":[{"id":"i1","texto":"Restos de verdura"},{"id":"i2","texto":"Botellas plásticas"},{"id":"i3","texto":"Yerba usada"},{"id":"i4","texto":"Cajas de cartón sin aplastar"},{"id":"i5","texto":"Pasto cortado"},{"id":"i6","texto":"Bandejas de telgopor"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los orgánicos dominan el peso; los envases dominan el volumen. Los dos problemas tienen soluciones distintas."}},{"slug":"residuos-1.s2.p7","orden":7,"grupo":"residuos-1.s2.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué conocer la composición","cuerpo":["Saber qué hay en la bolsa permite decidir qué hacer con cada parte: los orgánicos pueden compostarse, el papel, el cartón, muchos plásticos, el vidrio y los metales pueden reciclarse, y otros residuos necesitan tratamientos especiales.","Si todo va mezclado, los orgánicos ensucian los materiales reciclables y se pierde casi todo. Separar en origen, en la casa, es lo que hace posible el resto."]},"solucion":{}},{"slug":"residuos-1.s2.p8","orden":8,"grupo":"residuos-1.s2.p8","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada material con lo que se puede hacer con él.","izquierda":[{"id":"a1","texto":"Restos de comida"},{"id":"a2","texto":"Cartón limpio"},{"id":"a3","texto":"Frascos de vidrio"},{"id":"a4","texto":"Latas de aluminio"}],"derecha":[{"id":"b1","texto":"Compostarlos"},{"id":"b2","texto":"Reciclarlo como papel"},{"id":"b3","texto":"Fundirlos para hacer vidrio nuevo"},{"id":"b4","texto":"Fundirlas para hacer aluminio nuevo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Casi todo lo que hay en la bolsa tiene un destino mejor que el relleno, si llega limpio y separado."}},{"slug":"residuos-1.s2.p9","orden":9,"grupo":"residuos-1.s2.p9","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué mezclar orgánicos con reciclables arruina el reciclaje.","items":[{"id":"i1","texto":"Los restos de comida van en la misma bolsa que el cartón"},{"id":"i2","texto":"El cartón se moja y se engrasa"},{"id":"i3","texto":"Las plantas de reciclaje no pueden usarlo"},{"id":"i4","texto":"Ese cartón termina en el relleno"},{"id":"i5","texto":"El cartón engrasado se recicla mejor"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Separar en origen es la condición para que todo lo demás funcione."}},{"slug":"residuos-1.s2.p10","orden":10,"grupo":"residuos-1.s2.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia genera 120 kg de residuos por mes y el 45 % son orgánicos. ¿Cuántos kilos de orgánicos genera por mes?","unidad":"kg","decimales":1},"solucion":{"valor":54,"tolerancia":1.08,"explicacion":"120 × 45 ÷ 100 = 54 kg de orgánicos por mes, que podrían compostarse en vez de viajar al relleno."}},{"slug":"residuos-1.s2.p10.v2","orden":10,"grupo":"residuos-1.s2.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia genera 90 kg de residuos por mes y el 50 % son orgánicos. ¿Cuántos kilos de orgánicos genera por mes?","unidad":"kg","decimales":1},"solucion":{"valor":45,"tolerancia":0.9,"explicacion":"90 × 50 ÷ 100 = 45 kg de orgánicos por mes, que podrían compostarse en vez de viajar al relleno."}},{"slug":"residuos-1.s2.p10.v3","orden":10,"grupo":"residuos-1.s2.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una familia genera 150 kg de residuos por mes y el 40 % son orgánicos. ¿Cuántos kilos de orgánicos genera por mes?","unidad":"kg","decimales":1},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"150 × 40 ÷ 100 = 60 kg de orgánicos por mes, que podrían compostarse en vez de viajar al relleno."}},{"slug":"residuos-1.s2.p11","orden":11,"grupo":"residuos-1.s2.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos residuos son orgánicos? Marcá todos.","opciones":[{"id":"o1","texto":"Cáscaras de huevo"},{"id":"o2","texto":"Yerba y saquitos de té"},{"id":"o3","texto":"Restos de poda"},{"id":"o4","texto":"Cáscaras de frutas"},{"id":"o5","texto":"Una bandeja de telgopor"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Orgánico es lo que viene de un ser vivo y se descompone. El telgopor es plástico."}},{"slug":"residuos-1.s2.p12","orden":12,"grupo":"residuos-1.s2.p12","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una ciudad quiere reducir a la mitad lo que manda al relleno. ¿Qué parte de la basura conviene atacar primero?","opciones":[{"id":"o1","texto":"Los orgánicos, que son casi la mitad del peso"},{"id":"o2","texto":"Los metales, que son muy valiosos"},{"id":"o3","texto":"El vidrio, porque es pesado"},{"id":"o4","texto":"Los textiles, porque son difíciles de tratar"}]},"solucion":{"clave":["o1"],"explicacion":"Elegir por impacto: los orgánicos son la fracción más grande y pueden tratarse cerca, con compostaje.","por_opcion":{"o3":"El vidrio pesa, pero es una parte chica del total, alrededor del 4 %."}}},{"slug":"residuos-1.s2.p13","orden":13,"grupo":"residuos-1.s2.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta conclusión de un estudio escolar y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los orgánicos fueron la parte más pesada de la bolsa."},{"id":"s2","texto":"Como los plásticos pesaron poco, no son un problema."},{"id":"s3","texto":"El cartón mojado con restos de comida ya no sirve para reciclar."},{"id":"s4","texto":"Separar no sirve porque todo termina mezclado igual."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Peso y volumen, y la importancia de separar en origen.","por_opcion":{"s2":"Pesan poco pero ocupan mucho volumen y duran mucho tiempo.","s4":"Donde hay recolección diferenciada o recicladores, separar permite recuperar materiales."}}},{"slug":"residuos-1.s2.p14","orden":14,"grupo":"residuos-1.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los residuos {{0}} son casi la mitad del peso de la basura; los plásticos pesan poco pero ocupan mucho {{1}}.","banco":[{"id":"w1","texto":"orgánicos"},{"id":"w2","texto":"volumen"},{"id":"w3","texto":"metales"},{"id":"w4","texto":"peso"},{"id":"w5","texto":"agua"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos datos que cambian cómo se piensa un plan de residuos."}}]},{"slug":"residuos-1.s3","orden":3,"tipo":"leccion","titulo_es":"Relleno sanitario o basural","bajada_es":"Dos destinos muy distintos para la misma basura: uno controlado y otro que contamina.","minutos":12,"pasos":[{"slug":"residuos-1.s3.p1","orden":1,"grupo":"residuos-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El basural a cielo abierto","cuerpo":["Un basural a cielo abierto es un lugar donde la basura se tira sin ningún control: sin impermeabilizar el suelo, sin cubrirla y muchas veces quemándola. En Argentina hay miles de basurales de este tipo, sobre todo en municipios chicos y medianos.","Contaminan el suelo y las napas con los líquidos que se forman, el aire con el humo de las quemas, atraen roedores e insectos que transmiten enfermedades y ponen en riesgo a quienes viven o trabajan cerca."]},"solucion":{}},{"slug":"residuos-1.s3.p2","orden":2,"grupo":"residuos-1.s3.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas causa un basural a cielo abierto? Marcá todos.","opciones":[{"id":"o1","texto":"Contamina el suelo y las napas"},{"id":"o2","texto":"El humo de las quemas contamina el aire"},{"id":"o3","texto":"Atrae ratas, moscas y mosquitos"},{"id":"o4","texto":"Pone en riesgo la salud de quienes viven cerca"},{"id":"o5","texto":"Produce agua potable para el barrio"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un basural afecta el suelo, el agua, el aire y la salud al mismo tiempo."}},{"slug":"residuos-1.s3.p3","orden":3,"grupo":"residuos-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El relleno sanitario","cuerpo":["Un relleno sanitario es una obra de ingeniería. El suelo se impermeabiliza con arcillas y membranas para que los líquidos no lleguen a las napas. La basura se compacta en capas y se cubre con tierra todos los días. Los líquidos se recogen y se tratan, y los gases se captan con caños.","En el área metropolitana de Buenos Aires, la empresa estatal CEAMSE opera los rellenos que reciben miles de toneladas por día. Un relleno controla la contaminación, pero ocupa tierra, se llena y sigue emitiendo gases durante décadas."]},"solucion":{}},{"slug":"residuos-1.s3.p4","orden":4,"grupo":"residuos-1.s3.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es característica de un relleno sanitario o de un basural a cielo abierto?","grupos":[{"id":"g1","nombre":"Relleno sanitario"},{"id":"g2","nombre":"Basural a cielo abierto"}],"items":[{"id":"i1","texto":"Membranas que impermeabilizan el suelo"},{"id":"i2","texto":"Quema de la basura"},{"id":"i3","texto":"Cobertura diaria con tierra"},{"id":"i4","texto":"Líquidos que se infiltran en el suelo"},{"id":"i5","texto":"Captación de gases con caños"},{"id":"i6","texto":"Basura expuesta a animales y lluvia"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La diferencia es el control: un relleno está diseñado para contener; un basural no contiene nada."}},{"slug":"residuos-1.s3.p5","orden":5,"grupo":"residuos-1.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lixiviados: el jugo de la basura","cuerpo":["Cuando llueve sobre la basura, el agua la atraviesa y arrastra sustancias: restos orgánicos, metales, químicos. Ese líquido se llama lixiviado, y es muy contaminante.","En un relleno, los lixiviados se juntan en el fondo impermeable y se bombean a una planta de tratamiento. En un basural, se infiltran directamente hacia las napas o escurren hacia arroyos."]},"solucion":{}},{"slug":"residuos-1.s3.p6","orden":6,"grupo":"residuos-1.s3.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un basural puede contaminar el agua de un pozo.","items":[{"id":"i1","texto":"Llueve sobre el basural"},{"id":"i2","texto":"El agua atraviesa la basura y arrastra sustancias"},{"id":"i3","texto":"Se forma un lixiviado muy contaminante"},{"id":"i4","texto":"El lixiviado se infiltra en el suelo sin barrera"},{"id":"i5","texto":"Llega a la napa de la que bebe un pozo cercano"},{"id":"i6","texto":"El lixiviado se purifica solo al tocar el suelo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Es la conexión entre residuos y agua que viste en la rama de Agua: lo que se tira en tierra puede terminar en el vaso."}},{"slug":"residuos-1.s3.p7","orden":7,"grupo":"residuos-1.s3.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un relleno sanitario no contamina nada, así que da igual cuánta basura se mande.","razones":[{"id":"r1","texto":"Porque igual ocupa tierra, emite gases y se llena"},{"id":"r2","texto":"Porque los rellenos son infinitos"},{"id":"r3","texto":"Porque la basura desaparece en el relleno"}]},"solucion":{"valor":false,"explicacion":"Controla mucho mejor que un basural, pero ocupa tierra, se llena, emite metano durante décadas y cuesta mucho. Mandar menos siempre es mejor.","clave":["r1"]}},{"slug":"residuos-1.s3.p8","orden":8,"grupo":"residuos-1.s3.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Metano: el gas de la basura","cuerpo":["En un relleno, la basura orgánica queda enterrada sin oxígeno. Ahí la descomponen microbios que producen metano, un gas de efecto invernadero que, como viste en el tronco, calienta muchas veces más que el CO₂ en un período de 100 años.","Los rellenos y basurales están entre las mayores fuentes de metano causadas por las personas. Captar ese gas y quemarlo o usarlo para generar electricidad reduce mucho su efecto."]},"solucion":{}},{"slug":"residuos-1.s3.p9","orden":9,"grupo":"residuos-1.s3.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué los restos de comida enterrados en un relleno producen metano?","opciones":[{"id":"o1","texto":"Porque se descomponen sin oxígeno"},{"id":"o2","texto":"Porque la tierra que los cubre tiene metano"},{"id":"o3","texto":"Porque los camiones los rocían con gas"},{"id":"o4","texto":"Porque los rellenos se construyen sobre pozos de gas"}]},"solucion":{"clave":["o1"],"explicacion":"Sin oxígeno, los microbios que descomponen producen metano. Con oxígeno, como en una compostera bien hecha, producen sobre todo CO₂ y mucho menos metano.","por_opcion":{"o3":"El metano lo producen microbios al descomponer lo orgánico sin aire."}}},{"slug":"residuos-1.s3.p10","orden":10,"grupo":"residuos-1.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno emite 2 toneladas de metano. Si el metano calienta unas 28 veces más que el CO₂ en 100 años, ¿cuántas toneladas de CO₂ equivalente son?","unidad":"t CO₂e","decimales":0},"solucion":{"valor":56,"tolerancia":1.12,"explicacion":"2 × 28 = 56 t de CO₂ equivalente. Es la cuenta del tronco: gases distintos, un mismo número para comparar."}},{"slug":"residuos-1.s3.p10.v2","orden":10,"grupo":"residuos-1.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno emite 5 toneladas de metano. Si el metano calienta unas 28 veces más que el CO₂ en 100 años, ¿cuántas toneladas de CO₂ equivalente son?","unidad":"t CO₂e","decimales":0},"solucion":{"valor":140,"tolerancia":2.8000000000000003,"explicacion":"5 × 28 = 140 t de CO₂ equivalente. Es la cuenta del tronco: gases distintos, un mismo número para comparar."}},{"slug":"residuos-1.s3.p10.v3","orden":10,"grupo":"residuos-1.s3.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un relleno emite 10 toneladas de metano. Si el metano calienta unas 28 veces más que el CO₂ en 100 años, ¿cuántas toneladas de CO₂ equivalente son?","unidad":"t CO₂e","decimales":0},"solucion":{"valor":280,"tolerancia":5.6000000000000005,"explicacion":"10 × 28 = 280 t de CO₂ equivalente. Es la cuenta del tronco: gases distintos, un mismo número para comparar."}},{"slug":"residuos-1.s3.p11","orden":11,"grupo":"residuos-1.s3.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término con su definición.","izquierda":[{"id":"a1","texto":"Lixiviado"},{"id":"a2","texto":"Relleno sanitario"},{"id":"a3","texto":"Basural a cielo abierto"},{"id":"a4","texto":"Biogás"}],"derecha":[{"id":"b1","texto":"Líquido contaminante que se forma en la basura"},{"id":"b2","texto":"Obra que aísla y controla los residuos"},{"id":"b3","texto":"Lugar de descarte sin controles"},{"id":"b4","texto":"Gas con metano que sale de lo orgánico enterrado"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro palabras que aparecen en cualquier discusión sobre el destino de la basura."}},{"slug":"residuos-1.s3.p12","orden":12,"grupo":"residuos-1.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta noticia local y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El municipio cerrará su basural y llevará los residuos a un relleno sanitario."},{"id":"s2","texto":"Así la basura dejará de generar metano."},{"id":"s3","texto":"El relleno tendrá membranas y tratamiento de lixiviados."},{"id":"s4","texto":"Por eso ya no hace falta reducir ni separar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Pasar de basural a relleno es un gran avance, pero no reemplaza reducir y recuperar.","por_opcion":{"s2":"El relleno también genera metano; puede captarse, pero no desaparece.","s4":"El relleno se llena y cuesta: reducir y separar sigue siendo clave."}}},{"slug":"residuos-1.s3.p13","orden":13,"grupo":"residuos-1.s3.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos destinos de un residuo orgánico de peor a mejor para el ambiente.","items":[{"id":"i1","texto":"Quemado en un basural a cielo abierto"},{"id":"i2","texto":"Enterrado en un relleno sin captación de gas"},{"id":"i3","texto":"Enterrado en un relleno con captación de gas"},{"id":"i4","texto":"Compostado"}],"extremos":["Peor","Mejor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cada paso mejora el control. El compostaje, que vas a ver en esta rama, evita el problema en el origen.","valores":{"i1":"humo, lixiviados y metano","i2":"metano a la atmósfera","i3":"metano captado en parte","i4":"vuelve al suelo como abono"}}},{"slug":"residuos-1.s3.p14","orden":14,"grupo":"residuos-1.s3.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En un relleno, lo orgánico se descompone sin {{0}} y produce {{1}}; el líquido que atraviesa la basura se llama {{2}}.","banco":[{"id":"w1","texto":"oxígeno"},{"id":"w2","texto":"metano"},{"id":"w3","texto":"lixiviado"},{"id":"w4","texto":"luz"},{"id":"w5","texto":"vapor"},{"id":"w6","texto":"compost"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas que explican por qué la basura orgánica es un problema climático."}}]},{"slug":"residuos-1.s4","orden":4,"tipo":"leccion","titulo_es":"La basura también tiene costo","bajada_es":"Cuánto cuesta recoger y enterrar, quién lo paga y por qué cada kilo que no se tira ahorra en toda la cadena.","minutos":11,"pasos":[{"slug":"residuos-1.s4.p1","orden":1,"grupo":"residuos-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El costo de la cadena","cuerpo":["Recoger, transportar y disponer residuos cuesta mucho: camiones, combustible, trabajadores, estaciones de transferencia y rellenos. En muchos municipios es uno de los gastos más grandes del presupuesto, y lo pagan todos los vecinos con sus tasas.","El costo suele crecer con la cantidad: más toneladas son más viajes de camión y más espacio en el relleno. Por eso cada kilo que no se genera, o que se recupera, ahorra plata a toda la ciudad."]},"solucion":{}},{"slug":"residuos-1.s4.p2","orden":2,"grupo":"residuos-1.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad gestiona 1.000 toneladas de residuos por día y cada tonelada le cuesta $50.000 entre recolección y disposición. ¿Cuánto gasta por día?","unidad":"$","decimales":0},"solucion":{"valor":50000000,"tolerancia":1000000,"explicacion":"1.000 × $50.000 = $50.000.000 por día. Por año, 365 veces eso."}},{"slug":"residuos-1.s4.p2.v2","orden":2,"grupo":"residuos-1.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad gestiona 500 toneladas de residuos por día y cada tonelada le cuesta $60.000 entre recolección y disposición. ¿Cuánto gasta por día?","unidad":"$","decimales":0},"solucion":{"valor":30000000,"tolerancia":600000,"explicacion":"500 × $60.000 = $30.000.000 por día. Por año, 365 veces eso."}},{"slug":"residuos-1.s4.p2.v3","orden":2,"grupo":"residuos-1.s4.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una ciudad gestiona 3.000 toneladas de residuos por día y cada tonelada le cuesta $45.000 entre recolección y disposición. ¿Cuánto gasta por día?","unidad":"$","decimales":0},"solucion":{"valor":135000000,"tolerancia":2700000,"explicacion":"3.000 × $45.000 = $135.000.000 por día. Por año, 365 veces eso."}},{"slug":"residuos-1.s4.p3","orden":3,"grupo":"residuos-1.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa ciudad de 1.000 toneladas por día reduce un 10 % lo que manda al relleno, ¿cuántas toneladas por día deja de enviar?","unidad":"toneladas","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"1.000 × 10 ÷ 100 = 100 toneladas por día menos: menos viajes de camión, menos espacio de relleno y menos gasto."}},{"slug":"residuos-1.s4.p3.v2","orden":3,"grupo":"residuos-1.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa ciudad de 500 toneladas por día reduce un 20 % lo que manda al relleno, ¿cuántas toneladas por día deja de enviar?","unidad":"toneladas","decimales":0},"solucion":{"valor":100,"tolerancia":2,"explicacion":"500 × 20 ÷ 100 = 100 toneladas por día menos: menos viajes de camión, menos espacio de relleno y menos gasto."}},{"slug":"residuos-1.s4.p3.v3","orden":3,"grupo":"residuos-1.s4.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si esa ciudad de 3.000 toneladas por día reduce un 15 % lo que manda al relleno, ¿cuántas toneladas por día deja de enviar?","unidad":"toneladas","decimales":0},"solucion":{"valor":450,"tolerancia":9,"explicacion":"3.000 × 15 ÷ 100 = 450 toneladas por día menos: menos viajes de camión, menos espacio de relleno y menos gasto."}},{"slug":"residuos-1.s4.p4","orden":4,"grupo":"residuos-1.s4.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los costos que no aparecen en la factura","cuerpo":["Hay costos que no se pagan en pesos: el metano que calienta el planeta, la contaminación del agua y el suelo cerca de basurales, la salud de quienes viven al lado, la tierra ocupada por rellenos durante décadas. Se llaman costos externos, porque no los paga quien genera el residuo."]},"solucion":{}},{"slug":"residuos-1.s4.p5","orden":5,"grupo":"residuos-1.s4.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un costo que se paga en la tasa municipal o un costo externo?","grupos":[{"id":"g1","nombre":"Se paga en la tasa"},{"id":"g2","nombre":"Costo externo"}],"items":[{"id":"i1","texto":"El combustible de los camiones"},{"id":"i2","texto":"El metano que calienta el planeta"},{"id":"i3","texto":"Los sueldos de los recolectores"},{"id":"i4","texto":"La napa contaminada cerca de un basural"},{"id":"i5","texto":"La operación del relleno"},{"id":"i6","texto":"Las enfermedades de quienes viven al lado"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los costos externos existen aunque nadie los facture. Reducir residuos baja los dos tipos."}},{"slug":"residuos-1.s4.p6","orden":6,"grupo":"residuos-1.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si la tasa de basura es baja, tirar mucho no tiene costo.","razones":[{"id":"r1","texto":"Porque hay costos externos que la tasa no refleja"},{"id":"r2","texto":"Porque la basura se gestiona gratis"},{"id":"r3","texto":"Porque los rellenos no ocupan tierra"}]},"solucion":{"valor":false,"explicacion":"La tasa no refleja los costos externos: contaminación, metano y salud. Y la cuenta del municipio la terminan pagando todos.","clave":["r1"]}},{"slug":"residuos-1.s4.p7","orden":7,"grupo":"residuos-1.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Quién genera, quién paga","cuerpo":["Hoy, la mayoría de los costos de los envases los paga el municipio, no quien los fabrica o vende. La responsabilidad extendida del productor (REP) es una idea que propone que las empresas que ponen envases en el mercado se hagan cargo de financiar su recuperación.","Varios países la aplican y en Argentina hay leyes provinciales y proyectos nacionales. La idea es que el costo del residuo entre en el precio del producto, y que las empresas tengan un incentivo para diseñar envases más fáciles de reciclar o reutilizar."]},"solucion":{}},{"slug":"residuos-1.s4.p8","orden":8,"grupo":"residuos-1.s4.p8","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué busca la responsabilidad extendida del productor?","opciones":[{"id":"o1","texto":"Que quien pone envases en el mercado financie su recuperación"},{"id":"o2","texto":"Que los vecinos paguen más tasa municipal por la basura"},{"id":"o3","texto":"Que se prohíban todos los envases de plástico"},{"id":"o4","texto":"Que los municipios dejen de recoger los residuos de envases"}]},"solucion":{"clave":["o1"],"explicacion":"Cuando el costo del residuo recae en quien lo diseña, aparece el incentivo para diseñarlo mejor.","por_opcion":{"o3":"No prohíbe: busca que el costo de gestión lo asuma el productor."}}},{"slug":"residuos-1.s4.p9","orden":9,"grupo":"residuos-1.s4.p9","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo la responsabilidad extendida del productor puede cambiar un envase.","items":[{"id":"i1","texto":"La empresa paga por cada tonelada de envases que vende"},{"id":"i2","texto":"Los envases difíciles de reciclar le cuestan más"},{"id":"i3","texto":"La empresa rediseña el envase para que sea reciclable o más liviano"},{"id":"i4","texto":"Llegan menos envases problemáticos al relleno"},{"id":"i5","texto":"Los vecinos pagan el rediseño con más tasa"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un incentivo bien puesto cambia decisiones de diseño que ningún vecino puede cambiar solo. Es lo tuyo y lo de todos del tronco."}},{"slug":"residuos-1.s4.p10","orden":10,"grupo":"residuos-1.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos son costos reales de tirar más basura? Marcá todos.","opciones":[{"id":"o1","texto":"Más viajes de camión y combustible"},{"id":"o2","texto":"Rellenos que se llenan antes"},{"id":"o3","texto":"Más metano en la atmósfera"},{"id":"o4","texto":"Más tierra ocupada por décadas"},{"id":"o5","texto":"Más agua potable en la ciudad"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Algunos se pagan en pesos, otros en ambiente y salud. Todos son reales."}},{"slug":"residuos-1.s4.p11","orden":11,"grupo":"residuos-1.s4.p11","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada idea con su ejemplo.","izquierda":[{"id":"a1","texto":"Costo interno"},{"id":"a2","texto":"Costo externo"},{"id":"a3","texto":"Responsabilidad extendida"},{"id":"a4","texto":"Ahorro en cadena"}],"derecha":[{"id":"b1","texto":"El sueldo de un recolector"},{"id":"b2","texto":"Una napa contaminada por lixiviados"},{"id":"b3","texto":"Una empresa financia la recuperación de sus envases"},{"id":"b4","texto":"Un kilo menos es menos camión y menos relleno"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro ideas económicas para pensar los residuos más allá de la bolsa."}},{"slug":"residuos-1.s4.p12","orden":12,"grupo":"residuos-1.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Recolectar residuos es uno de los grandes gastos de un municipio."},{"id":"s2","texto":"Si la basura no la veo, no me cuesta nada."},{"id":"s3","texto":"Reducir un 10 % la basura ahorra camiones y espacio de relleno."},{"id":"s4","texto":"La responsabilidad extendida del productor significa que los vecinos paguen los envases."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La basura tiene costos visibles e invisibles, y alguien siempre los paga.","por_opcion":{"s2":"Se paga con las tasas y con costos externos como la contaminación.","s4":"Es al revés: busca que los productores financien la recuperación."}}},{"slug":"residuos-1.s4.p13","orden":13,"grupo":"residuos-1.s4.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los costos que no paga quien genera el residuo se llaman {{0}}; la responsabilidad extendida busca que los pague el {{1}}.","banco":[{"id":"w1","texto":"externos"},{"id":"w2","texto":"productor"},{"id":"w3","texto":"internos"},{"id":"w4","texto":"vecino"},{"id":"w5","texto":"municipio"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos conceptos para discutir quién paga por la basura."}}]},{"slug":"residuos-1.s5","orden":5,"tipo":"leccion","titulo_es":"Quienes recuperan","bajada_es":"Recicladores urbanos, cooperativas y centros verdes: el trabajo que hace posible el reciclaje en Argentina.","minutos":11,"pasos":[{"slug":"residuos-1.s5.p1","orden":1,"grupo":"residuos-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los recicladores urbanos","cuerpo":["En Argentina, gran parte de los materiales que se reciclan son recuperados por recicladores urbanos, también llamados cartoneros o recuperadores. Recorren las calles, separan papel, cartón, plásticos, vidrio y metales, y los venden a la industria.","Durante mucho tiempo fue un trabajo informal y sin derechos. Con los años, muchos se organizaron en cooperativas y en organizaciones como la Federación Argentina de Cartoneros, Carreros y Recicladores (FACCyR), y varios municipios los incorporaron a su sistema de gestión."]},"solucion":{}},{"slug":"residuos-1.s5.p2","orden":2,"grupo":"residuos-1.s5.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Quiénes recuperan gran parte de los materiales reciclables en las ciudades argentinas?","opciones":[{"id":"o1","texto":"Los recicladores urbanos y sus cooperativas"},{"id":"o2","texto":"Las fábricas de envases directamente en las casas"},{"id":"o3","texto":"Los camiones compactadores comunes"},{"id":"o4","texto":"Los rellenos sanitarios al enterrar la basura"}]},"solucion":{"clave":["o1"],"explicacion":"Sin los recicladores, las tasas de reciclaje del país serían mucho más bajas.","por_opcion":{"o3":"El camión común compacta todo junto: ahí se pierde casi todo lo reciclable."}}},{"slug":"residuos-1.s5.p3","orden":3,"grupo":"residuos-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Basura Cero y la inclusión","cuerpo":["En la Ciudad de Buenos Aires, leyes como la Ley 992 reconocieron a los recuperadores urbanos, y la Ley 1.854, conocida como \"Basura Cero\", fijó el objetivo de reducir progresivamente lo que se entierra y promover la separación en origen y el reciclaje.","Las cooperativas operan centros verdes: lugares donde el material separado se clasifica, se enfarda y se vende. Cuanto más limpio y separado llega el material, más vale y mejores son las condiciones de ese trabajo."]},"solucion":{}},{"slug":"residuos-1.s5.p4","orden":4,"grupo":"residuos-1.s5.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de una caja de cartón que separaste en tu casa.","items":[{"id":"i1","texto":"La separás limpia y seca en casa"},{"id":"i2","texto":"Un reciclador o un camión diferenciado la recoge"},{"id":"i3","texto":"Llega a un centro verde"},{"id":"i4","texto":"Se clasifica y se enfarda con otros cartones"},{"id":"i5","texto":"Se vende a una fábrica de papel"},{"id":"i6","texto":"Se entierra en el relleno junto con los orgánicos"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Tu separación es el primer eslabón. Si falla, los demás no pueden hacer nada."}},{"slug":"residuos-1.s5.p5","orden":5,"grupo":"residuos-1.s5.p5","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda al trabajo de los recicladores urbanos? Marcá todo lo que corresponde.","opciones":[{"id":"o1","texto":"Separar los reciclables limpios y secos"},{"id":"o2","texto":"No mezclar vidrio roto con el resto sin protegerlo"},{"id":"o3","texto":"Aplastar las cajas y botellas"},{"id":"o4","texto":"Sacar los reciclables en el horario indicado"},{"id":"o5","texto":"Mezclar restos de comida con el cartón"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Material limpio vale más y es más seguro de manipular. Es respeto y es eficiencia."}},{"slug":"residuos-1.s5.p6","orden":6,"grupo":"residuos-1.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Separar los reciclables en casa no tiene efecto si no hay camión diferenciado.","razones":[{"id":"r1","texto":"Porque recicladores y puntos verdes pueden recuperarlo"},{"id":"r2","texto":"Porque separar hace que el material se degrade"},{"id":"r3","texto":"Porque los camiones comunes separan todo solos"}]},"solucion":{"valor":false,"explicacion":"En muchas ciudades los recicladores urbanos recuperan el material separado aunque no haya camión especial. Además, hay puntos verdes donde llevarlo.","clave":["r1"]}},{"slug":"residuos-1.s5.p7","orden":7,"grupo":"residuos-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un trabajo con riesgos","cuerpo":["Revolver bolsas mezcladas expone a los recicladores a cortes con vidrios, agujas y latas, a restos de comida en descomposición y a químicos. Las cooperativas organizadas trabajan para tener equipamiento, galpones, obra social y un ingreso más estable.","Separar bien en casa no solo mejora el reciclaje: reduce los riesgos de quien después toca esos materiales."]},"solucion":{}},{"slug":"residuos-1.s5.p8","orden":8,"grupo":"residuos-1.s5.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta acción en casa hace más seguro o más riesgoso el trabajo de un reciclador?","grupos":[{"id":"g1","nombre":"Más seguro"},{"id":"g2","nombre":"Más riesgoso"}],"items":[{"id":"i1","texto":"Envolver el vidrio roto en papel y marcarlo"},{"id":"i2","texto":"Tirar agujas sueltas en la bolsa"},{"id":"i3","texto":"Separar los reciclables secos de los orgánicos"},{"id":"i4","texto":"Mezclar vidrio roto con cartón"},{"id":"i5","texto":"Cerrar bien las bolsas"},{"id":"i6","texto":"Poner químicos en botellas de bebida"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La bolsa que sacás la toca otra persona. Pensarlo cambia cómo la armás."}},{"slug":"residuos-1.s5.p9","orden":9,"grupo":"residuos-1.s5.p9","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada lugar o actor con su función.","izquierda":[{"id":"a1","texto":"Centro verde"},{"id":"a2","texto":"Cooperativa de recicladores"},{"id":"a3","texto":"Punto verde"},{"id":"a4","texto":"Industria recicladora"}],"derecha":[{"id":"b1","texto":"Clasifica y enfarda el material separado"},{"id":"b2","texto":"Organiza el trabajo de recuperación"},{"id":"b3","texto":"Lugar donde los vecinos dejan reciclables"},{"id":"b4","texto":"Transforma el material en producto nuevo"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El reciclaje es una cadena de actores. Cada uno depende del anterior."}},{"slug":"residuos-1.s5.p10","orden":10,"grupo":"residuos-1.s5.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una vecina pregunta si vale la pena lavar un frasco antes de separarlo. ¿Qué le responderías?","opciones":[{"id":"o1","texto":"Sí, con un enjuague alcanza: el material limpio vale más"},{"id":"o2","texto":"No, en la planta lo lavan todo con máquinas especiales"},{"id":"o3","texto":"No, el vidrio sucio se recicla igual de bien que el limpio"},{"id":"o4","texto":"Sí, pero solo si es un frasco de vidrio muy caro"}]},"solucion":{"clave":["o1"],"explicacion":"No hace falta dejarlo impecable: con sacarle los restos y enjuagarlo alcanza para no ensuciar el resto.","por_opcion":{"o3":"Los restos de comida contaminan otros materiales y bajan su valor."}}},{"slug":"residuos-1.s5.p11","orden":11,"grupo":"residuos-1.s5.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario en redes y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los cartoneros recuperan buena parte del material reciclable del país."},{"id":"s2","texto":"Separar en casa es inútil: los cartoneros revuelven todo igual."},{"id":"s3","texto":"Muchos se organizaron en cooperativas."},{"id":"s4","texto":"Es un trabajo sin ningún riesgo."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Reconocer el trabajo de los recicladores es también cambiar cómo armamos la bolsa.","por_opcion":{"s2":"Si el material ya viene separado, no tienen que revolver: es más limpio, seguro y valioso.","s4":"Hay riesgos de cortes, pinchazos e infecciones, sobre todo con bolsas mezcladas."}}},{"slug":"residuos-1.s5.p12","orden":12,"grupo":"residuos-1.s5.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas bolsas de la más valiosa a la menos valiosa para un centro verde.","items":[{"id":"i1","texto":"Cartón seco y aplastado"},{"id":"i2","texto":"Botellas plásticas enjuagadas"},{"id":"i3","texto":"Reciclables secos mezclados entre sí"},{"id":"i4","texto":"Reciclables mezclados con restos de comida"}],"extremos":["Más valiosa","Menos valiosa"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Cuanto mejor separado y más limpio, más material se recupera y mejor se paga ese trabajo.","valores":{"i1":"se vende directo","i2":"se venden tras clasificar","i3":"hay que clasificar todo","i4":"casi todo se pierde"}}},{"slug":"residuos-1.s5.p13","orden":13,"grupo":"residuos-1.s5.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Los recicladores urbanos llevan el material a centros {{0}}, donde se clasifica y se {{1}} para venderlo a la {{2}}.","banco":[{"id":"w1","texto":"verdes"},{"id":"w2","texto":"enfarda"},{"id":"w3","texto":"industria"},{"id":"w4","texto":"rojos"},{"id":"w5","texto":"entierra"},{"id":"w6","texto":"municipalidad"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"El recorrido del material separado, en una línea."}}]},{"slug":"residuos-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: qué pasa con lo que tirás","bajada_es":"Qué es un residuo, composición, destino, costos y recuperadores, mezclados.","minutos":8,"pasos":[{"slug":"residuos-1.s6.p1","orden":1,"grupo":"residuos-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Qué pasa con lo que tirás». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"residuos-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la semana de la familia Sosa","bajada_es":"La familia Sosa pesó su basura durante una semana. Con los números, encontrá qué hacer primero. Aprobalo para hacer crecer la rama.","minutos":10,"pasos":[{"slug":"residuos-1.s7.p1","orden":1,"grupo":"residuos-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos de los Sosa","cuerpo":["Los Sosa son 4 y viven en un municipio que manda todo a un relleno sanitario. Durante una semana pesaron su basura: 30 kilos en total.","Separaron por tipo: 15 kg de restos de comida y yerba, 5 kg de papel y cartón, 4 kg de plásticos, 2 kg de vidrio, 1 kg de metales y 3 kg de pañales y otros. En su barrio pasan recicladores dos veces por semana y hay un punto verde a diez cuadras."]},"solucion":{}},{"slug":"residuos-1.s7.p2","orden":2,"grupo":"residuos-1.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kilos por persona por día generaron los Sosa?","unidad":"kg","decimales":2,"contexto":"30 kg en una semana, 4 personas."},"solucion":{"valor":1.07,"tolerancia":0.02,"explicacion":"30 kg ÷ 4 personas ÷ 7 días ≈ 1,07 kg por persona por día: muy cerca del promedio argentino."}},{"slug":"residuos-1.s7.p3","orden":3,"grupo":"residuos-1.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje de su basura son orgánicos?","unidad":"%","decimales":0,"contexto":"15 kg de orgánicos sobre 30 kg totales."},"solucion":{"valor":50,"tolerancia":1,"explicacion":"15 ÷ 30 × 100 = 50 %. La mitad de la bolsa podría compostarse."}},{"slug":"residuos-1.s7.p4","orden":4,"grupo":"residuos-1.s7.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos kilos por semana son reciclables secos (papel y cartón, plásticos, vidrio y metales)?","unidad":"kg","decimales":0,"contexto":"Papel y cartón 5 kg, plásticos 4, vidrio 2, metales 1."},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"5 + 4 + 2 + 1 = 12 kg. El 40 % de su basura podría ir a los recicladores o al punto verde."}},{"slug":"residuos-1.s7.p5","orden":5,"grupo":"residuos-1.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los Sosa compostan el 100 % de sus orgánicos (15 kg) y separan el 100 % de sus reciclables secos (12 kg), ¿cuántos kilos por semana seguirían yendo al relleno?","unidad":"kg","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"Compostan 15 kg y separan 12 kg: 30 − 15 − 12 = 3 kg al relleno por semana."}},{"slug":"residuos-1.s7.p5.v2","orden":5,"grupo":"residuos-1.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los Sosa compostan el 80 % de sus orgánicos (15 kg) y separan el 75 % de sus reciclables secos (12 kg), ¿cuántos kilos por semana seguirían yendo al relleno?","unidad":"kg","decimales":1},"solucion":{"valor":9,"tolerancia":0.18,"explicacion":"Compostan 12 kg y separan 9 kg: 30 − 12 − 9 = 9 kg al relleno por semana."}},{"slug":"residuos-1.s7.p5.v3","orden":5,"grupo":"residuos-1.s7.p5","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si los Sosa compostan el 60 % de sus orgánicos (15 kg) y separan el 50 % de sus reciclables secos (12 kg), ¿cuántos kilos por semana seguirían yendo al relleno?","unidad":"kg","decimales":1},"solucion":{"valor":15,"tolerancia":0.3,"explicacion":"Compostan 9 kg y separan 6 kg: 30 − 9 − 6 = 15 kg al relleno por semana."}},{"slug":"residuos-1.s7.p6","orden":6,"grupo":"residuos-1.s7.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená las acciones posibles de los Sosa por cuántos kilos sacarían del relleno por semana, de más a menos.","items":[{"id":"i1","texto":"Compostar los orgánicos"},{"id":"i2","texto":"Separar papel y cartón"},{"id":"i3","texto":"Separar plásticos"},{"id":"i4","texto":"Separar vidrio"},{"id":"i5","texto":"Separar metales"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El compostaje es el cambio más grande por peso. Separar los secos suma casi lo mismo entre todos.","valores":{"i1":"hasta 15 kg","i2":"hasta 5 kg","i3":"hasta 4 kg","i4":"hasta 2 kg","i5":"hasta 1 kg"}}},{"slug":"residuos-1.s7.p7","orden":7,"grupo":"residuos-1.s7.p7","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Los Sosa no tienen patio. ¿Qué pueden hacer con los orgánicos?","opciones":[{"id":"o1","texto":"Buscar una compostera de balcón o un compostaje comunitario"},{"id":"o2","texto":"Tirarlos por el inodoro para que no ocupen lugar"},{"id":"o3","texto":"Nada: sin patio no hay forma de compostar"},{"id":"o4","texto":"Mezclarlos con el cartón para que pesen menos"}]},"solucion":{"clave":["o1"],"explicacion":"Sin patio también se puede: vermicompostaje en balcón o llevar los orgánicos a un punto de compostaje comunitario.","por_opcion":{"o3":"Hay composteras chicas para interiores y programas de compostaje barrial."}}},{"slug":"residuos-1.s7.p8","orden":8,"grupo":"residuos-1.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Los Sosa escriben su plan en la heladera. Marcá lo que no conviene.","segmentos":[{"id":"s1","texto":"Separamos cartón, plástico, vidrio y metal limpios y secos."},{"id":"s2","texto":"Guardamos los restos de comida junto con el cartón hasta que pasen los recicladores."},{"id":"s3","texto":"Probamos una compostera de balcón para los orgánicos."},{"id":"s4","texto":"El vidrio roto va suelto en la bolsa de reciclables."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen plan separa bien, piensa en quien recibe la bolsa y ataca primero lo más pesado.","por_opcion":{"s2":"Los orgánicos ensucian el cartón y lo vuelven irrecuperable.","s4":"Hay que envolverlo y marcarlo: es un riesgo para quien lo manipula."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"residuos-2","rama":"residuos","orden":2,"nivel":1,"titulo_es":"Reducir, reutilizar, reciclar","bajada_es":"No son tres opciones iguales: son una escalera. Por qué reducir le gana a reciclar, y cómo funciona el reciclaje por dentro.","objetivos_es":["Ordenar las opciones de gestión según la jerarquía de residuos","Identificar formas concretas de reducir residuos en la fuente","Evaluar cuándo reutilizar un objeto compensa su fabricación","Explicar las etapas del reciclaje y los límites de cada material","Argumentar por qué el reciclaje solo no resuelve el problema"],"repasa":["residuos-1","tronco-2","tronco-3"],"requiere_tronco":1,"fuentes":["ellen-macarthur","yale-reciclaje","unep-plasticos","oecd-plasticos","mst-bolsas-2018","iai-reciclaje-aluminio","ley-25916-residuos","epa"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"residuos-2.s1","orden":1,"tipo":"leccion","titulo_es":"La escalera de los residuos","bajada_es":"Prevenir, reutilizar, reciclar, recuperar energía y enterrar: un orden con fundamento.","minutos":11,"pasos":[{"slug":"residuos-2.s1.p1","orden":1,"grupo":"residuos-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"No todas las opciones valen lo mismo","cuerpo":["La jerarquía de residuos ordena las opciones de mejor a peor para el ambiente: primero prevenir (que el residuo no exista), después reutilizar, después reciclar, después recuperar energía y, como último recurso, disponer en un relleno.","Cada escalón hacia arriba ahorra más materiales, energía y emisiones. Reciclar es bueno, pero es el tercer escalón, no el primero."],"lista":["1. Prevenir y reducir","2. Reutilizar","3. Reciclar","4. Recuperar energía","5. Disponer en relleno"]},"solucion":{}},{"slug":"residuos-2.s1.p2","orden":2,"grupo":"residuos-2.s1.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená la jerarquía de residuos de la mejor a la peor opción.","items":[{"id":"i1","texto":"Prevenir que el residuo exista"},{"id":"i2","texto":"Reutilizar el objeto"},{"id":"i3","texto":"Reciclar el material"},{"id":"i4","texto":"Recuperar energía"},{"id":"i5","texto":"Enterrar en un relleno sanitario"}],"extremos":["Mejor","Peor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una escalera: cuanto más arriba se resuelve, menos se pierde."}},{"slug":"residuos-2.s1.p3","orden":3,"grupo":"residuos-2.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué ese orden","cuerpo":["Fabricar algo nuevo usa materias primas, agua y energía. Si un objeto no se fabrica, se ahorra todo eso. Si se reutiliza, se ahorra casi todo. Si se recicla, se recupera el material, pero hay que recolectarlo, transportarlo, limpiarlo, fundirlo o triturarlo y volver a fabricar: se ahorra una parte.","Recuperar energía quemando residuos aprovecha algo, pero el material se pierde. Enterrar pierde todo."]},"solucion":{}},{"slug":"residuos-2.s1.p4","orden":4,"grupo":"residuos-2.s1.p4","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué reutilizar un frasco ahorra más que reciclarlo.","items":[{"id":"i1","texto":"El frasco reutilizado sigue siendo un frasco"},{"id":"i2","texto":"No hace falta fundirlo ni fabricar uno nuevo"},{"id":"i3","texto":"Se ahorra la energía de fundir el vidrio a más de 1.000 °C"},{"id":"i4","texto":"Se evitan las emisiones de esa energía"},{"id":"i5","texto":"Reutilizar el frasco lo vuelve más pesado"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Reciclar vidrio es bueno, pero fundirlo pide mucha energía. Lavarlo y volver a llenarlo, muy poca."}},{"slug":"residuos-2.s1.p5","orden":5,"grupo":"residuos-2.s1.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿En qué escalón de la jerarquía está cada acción?","grupos":[{"id":"g1","nombre":"Prevenir o reducir"},{"id":"g2","nombre":"Reutilizar"},{"id":"g3","nombre":"Reciclar"}],"items":[{"id":"i1","texto":"No aceptar un folleto que no vas a leer"},{"id":"i2","texto":"Usar una botella retornable"},{"id":"i3","texto":"Separar latas para que se fundan"},{"id":"i4","texto":"Comprar a granel con tu propio frasco"},{"id":"i5","texto":"Arreglar una silla rota"},{"id":"i6","texto":"Llevar el cartón al punto verde"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada acción cuenta, pero no cuenta igual. Las de arriba evitan todo lo que viene después."}},{"slug":"residuos-2.s1.p6","orden":6,"grupo":"residuos-2.s1.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si todo lo que uso se recicla, no importa cuánto consumo.","razones":[{"id":"r1","texto":"Porque reciclar tiene costos y pérdidas en cada vuelta"},{"id":"r2","texto":"Porque reciclar crea materiales nuevos de la nada"},{"id":"r3","texto":"Porque el reciclaje no usa energía"}]},"solucion":{"valor":false,"explicacion":"Reciclar recupera una parte, pero cuesta energía, transporte y agua, y nunca recupera el 100 %. Reducir sigue siendo mejor.","clave":["r1"]}},{"slug":"residuos-2.s1.p7","orden":7,"grupo":"residuos-2.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un ejemplo con números","cuerpo":["Supongamos que fabricar una botella nueva de vidrio cuesta 100 unidades de energía. Reciclar una botella usada para hacer otra puede costar alrededor de 70 a 80, porque fundir vidrio reciclado pide algo menos de energía que partir de arena. Lavar y volver a llenar una botella retornable puede costar menos de 10.","Los números exactos cambian mucho según el caso, pero el orden casi nunca cambia: reutilizar le gana a reciclar, y reciclar le gana a fabricar de cero."]},"solucion":{}},{"slug":"residuos-2.s1.p8","orden":8,"grupo":"residuos-2.s1.p8","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones para tener una botella llena de nuevo, de más a menos energía (ejemplo aproximado).","items":[{"id":"i1","texto":"Fabricar una botella nueva desde arena"},{"id":"i2","texto":"Fabricar una botella con vidrio reciclado"},{"id":"i3","texto":"Lavar y rellenar una botella retornable"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3"],"explicacion":"El orden de la jerarquía se ve en la energía. La retornable no necesita volver a fundir nada.","valores":{"i1":"≈ 100 unidades","i2":"≈ 70-80 unidades","i3":"menos de 10 unidades"}}},{"slug":"residuos-2.s1.p9","orden":9,"grupo":"residuos-2.s1.p9","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tenés un frasco de vidrio vacío en buen estado. ¿Cuál es la mejor opción según la jerarquía?","opciones":[{"id":"o1","texto":"Usarlo de nuevo para guardar algo"},{"id":"o2","texto":"Llevarlo al punto verde para reciclarlo"},{"id":"o3","texto":"Tirarlo con la basura común"},{"id":"o4","texto":"Romperlo para que ocupe menos lugar en el tacho"}]},"solucion":{"clave":["o1"],"explicacion":"Si el frasco sirve, usarlo es el escalón más alto disponible. Cuando ya no sirva, el reciclaje.","por_opcion":{"o3":"Es la peor opción: se pierde todo el material y la energía de fabricarlo."}}},{"slug":"residuos-2.s1.p10","orden":10,"grupo":"residuos-2.s1.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas acciones están en el escalón más alto, prevenir? Marcá todas.","opciones":[{"id":"o1","texto":"Rechazar una bolsa cuando no la necesitás"},{"id":"o2","texto":"Comprar productos con menos envoltorio"},{"id":"o3","texto":"Planificar las compras para no tirar comida"},{"id":"o4","texto":"Separar las botellas para el reciclaje"},{"id":"o5","texto":"Llevar las pilas a un punto de recolección"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Prevenir es actuar antes de que el residuo exista. Separar y llevar a un punto verde es bueno, pero ya hay residuo."}},{"slug":"residuos-2.s1.p11","orden":11,"grupo":"residuos-2.s1.p11","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este afiche escolar y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las tres R son reducir, reutilizar y reciclar."},{"id":"s2","texto":"Las tres valen lo mismo: da igual cuál hagas."},{"id":"s3","texto":"Enterrar es la última opción."},{"id":"s4","texto":"Reciclar es la mejor forma de cuidar el ambiente."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El orden de las R es la parte más importante del mensaje, y la que más se olvida.","por_opcion":{"s2":"Son una jerarquía: reducir evita más impacto que reutilizar, y reutilizar más que reciclar.","s4":"Es buena, pero está por debajo de reducir y reutilizar."}}},{"slug":"residuos-2.s1.p12","orden":12,"grupo":"residuos-2.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En la jerarquía de residuos, primero se busca {{0}}, después {{1}} y recién después {{2}}.","banco":[{"id":"w1","texto":"reducir"},{"id":"w2","texto":"reutilizar"},{"id":"w3","texto":"reciclar"},{"id":"w4","texto":"enterrar"},{"id":"w5","texto":"quemar"},{"id":"w6","texto":"comprar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las tres R, en el orden que de verdad importa."}},{"slug":"residuos-2.s1.p13","orden":13,"grupo":"residuos-2.s1.p13","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada escalón con su ejemplo.","izquierda":[{"id":"a1","texto":"Prevenir"},{"id":"a2","texto":"Reutilizar"},{"id":"a3","texto":"Reciclar"},{"id":"a4","texto":"Disponer"}],"derecha":[{"id":"b1","texto":"No imprimir un documento que se puede leer en pantalla"},{"id":"b2","texto":"Usar la hoja impresa del otro lado"},{"id":"b3","texto":"Separar el papel para hacer papel nuevo"},{"id":"b4","texto":"Tirar el papel con restos de comida"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El mismo material, cuatro destinos distintos. Cuanto más arriba, menos se pierde."}}]},{"slug":"residuos-2.s2","orden":2,"tipo":"leccion","titulo_es":"Reducir: el residuo que no existe","bajada_es":"Envases, descartables, compras y comida: dónde nace la basura y cómo evitar que nazca.","minutos":12,"pasos":[{"slug":"residuos-2.s2.p1","orden":1,"grupo":"residuos-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La basura se decide al comprar","cuerpo":["Buena parte de lo que termina en la bolsa entró a la casa en el changuito: envases, bolsas, bandejas, envoltorios. Cada decisión de compra decide también qué residuos vamos a tener.","Reducir no es privarse de todo: es elegir, cuando se puede, la opción que genera menos residuo para la misma necesidad."]},"solucion":{}},{"slug":"residuos-2.s2.p2","orden":2,"grupo":"residuos-2.s2.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Cuál de las dos opciones genera menos residuo?","grupos":[{"id":"g1","nombre":"Menos residuo"},{"id":"g2","nombre":"Más residuo"}],"items":[{"id":"i1","texto":"Fruta suelta en tu propia bolsa"},{"id":"i2","texto":"Fruta en bandeja de telgopor con film"},{"id":"i3","texto":"Detergente en envase grande o recarga"},{"id":"i4","texto":"Detergente en muchos envases chicos"},{"id":"i5","texto":"Agua de la canilla en botella reutilizable"},{"id":"i6","texto":"Agua en botellitas descartables"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La misma necesidad, distinta cantidad de envase. Muchas veces la opción con menos residuo también es más barata."}},{"slug":"residuos-2.s2.p3","orden":3,"grupo":"residuos-2.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los descartables","cuerpo":["Los objetos de un solo uso —vasos, cubiertos, sorbetes, bolsas livianas, bandejas— se fabrican para usarse minutos y duran como residuo décadas o siglos. Son chicos uno por uno, pero se usan por miles de millones.","Muchas ciudades del país y del mundo restringieron bolsas livianas y algunos descartables. El cambio más efectivo, igual, es el de hábito: llevar la bolsa, el vaso o la botella propios."]},"solucion":{}},{"slug":"residuos-2.s2.p4","orden":4,"grupo":"residuos-2.s2.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 4 personas cada una usa 3 bolsas descartables por semana. ¿Cuántas bolsas usan en un año de 52 semanas?","unidad":"bolsas","decimales":0},"solucion":{"valor":624,"tolerancia":12.48,"explicacion":"3 × 4 × 52 = 624 bolsas por año. Una bolsa reutilizable reemplaza cientos de ellas."}},{"slug":"residuos-2.s2.p4.v2","orden":4,"grupo":"residuos-2.s2.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 3 personas cada una usa 2 bolsas descartables por semana. ¿Cuántas bolsas usan en un año de 52 semanas?","unidad":"bolsas","decimales":0},"solucion":{"valor":312,"tolerancia":6.24,"explicacion":"2 × 3 × 52 = 312 bolsas por año. Una bolsa reutilizable reemplaza cientos de ellas."}},{"slug":"residuos-2.s2.p4.v3","orden":4,"grupo":"residuos-2.s2.p4","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En una casa de 2 personas cada una usa 5 bolsas descartables por semana. ¿Cuántas bolsas usan en un año de 52 semanas?","unidad":"bolsas","decimales":0},"solucion":{"valor":520,"tolerancia":10.4,"explicacion":"5 × 2 × 52 = 520 bolsas por año. Una bolsa reutilizable reemplaza cientos de ellas."}},{"slug":"residuos-2.s2.p5","orden":5,"grupo":"residuos-2.s2.p5","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un vaso descartable se usa minutos, pero puede durar como residuo muchísimo más tiempo.","razones":[{"id":"r1","texto":"Porque el material dura mucho más que su uso"},{"id":"r2","texto":"Porque el vaso se desintegra al terminar de usarse"},{"id":"r3","texto":"Porque los descartables se reciclan siempre solos"}]},"solucion":{"valor":true,"explicacion":"Es la paradoja del descartable: diseñado para durar como producto unos minutos y como residuo, décadas o siglos si es de plástico.","clave":["r1"]}},{"slug":"residuos-2.s2.p6","orden":6,"grupo":"residuos-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Comprar a granel y recargar","cuerpo":["Comprar a granel —legumbres, cereales, especias, productos de limpieza— con frascos o bolsas propias evita muchos envases. Los sistemas de recarga (de detergente, de agua en bidones, de gas en garrafas) hacen lo mismo: el envase vuelve y se llena otra vez.","No siempre es posible, pero donde existe, reduce el residuo desde la raíz."]},"solucion":{}},{"slug":"residuos-2.s2.p7","orden":7,"grupo":"residuos-2.s2.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estas prácticas reducen residuos en la fuente? Marcá todas.","opciones":[{"id":"o1","texto":"Comprar legumbres a granel con frasco propio"},{"id":"o2","texto":"Usar un sistema de recarga de detergente"},{"id":"o3","texto":"Llevar un termo en lugar de comprar café en vaso descartable"},{"id":"o4","texto":"Pedir la comida para llevar sin cubiertos descartables"},{"id":"o5","texto":"Comprar agua en botellitas y separarlas para reciclar"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Separar botellitas ayuda, pero el residuo ya existe. Las otras cuatro evitan que exista."}},{"slug":"residuos-2.s2.p8","orden":8,"grupo":"residuos-2.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La comida: el residuo más pesado","cuerpo":["Como viste en la unidad anterior, los restos orgánicos son casi la mitad de la basura. Una parte son cáscaras y restos inevitables, pero otra es comida que se compró y no se comió: se venció, se echó a perder o sobró.","Planificar las compras, guardar bien los alimentos, usar primero lo que vence antes y aprovechar las sobras reduce la bolsa y, además, ahorra plata. El desperdicio de alimentos se ve en detalle en la rama de Alimentación."]},"solucion":{}},{"slug":"residuos-2.s2.p9","orden":9,"grupo":"residuos-2.s2.p9","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para reducir la comida que se tira en una casa.","items":[{"id":"i1","texto":"Revisar qué hay en la heladera y la alacena"},{"id":"i2","texto":"Planificar las comidas de la semana"},{"id":"i3","texto":"Hacer una lista y comprar solo lo necesario"},{"id":"i4","texto":"Guardar bien y poner adelante lo que vence antes"},{"id":"i5","texto":"Aprovechar las sobras en otra comida"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Mirar, planificar, comprar justo, guardar bien y aprovechar: la comida que no se tira es residuo que nunca existió."}},{"slug":"residuos-2.s2.p10","orden":10,"grupo":"residuos-2.s2.p10","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué reduce más la basura de una familia: separar los envases o dejar de tirar comida que se echa a perder?","opciones":[{"id":"o1","texto":"Depende, pero la comida suele pesar mucho más"},{"id":"o2","texto":"Separar envases, porque los plásticos son lo peor"},{"id":"o3","texto":"Son exactamente iguales siempre"},{"id":"o4","texto":"Ninguna de las dos cambia la cantidad de basura"}]},"solucion":{"clave":["o1"],"explicacion":"Por peso, la comida desperdiciada suele ser mucho más que los envases. Las dos acciones suman, y conviene hacer ambas.","por_opcion":{"o3":"Pesan y funcionan distinto: la comida es una parte muy grande del peso de la bolsa."}}},{"slug":"residuos-2.s2.p11","orden":11,"grupo":"residuos-2.s2.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una lista de compras reduce la basura.","items":[{"id":"i1","texto":"Se revisa qué hay antes de salir"},{"id":"i2","texto":"Se compra solo lo que se va a usar"},{"id":"i3","texto":"Se vence y se echa a perder menos comida"},{"id":"i4","texto":"Llegan menos orgánicos a la bolsa"},{"id":"i5","texto":"La lista hace que la comida dure el doble"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Una decisión antes de comprar evita un residuo días después."}},{"slug":"residuos-2.s2.p12","orden":12,"grupo":"residuos-2.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé estos consejos y marcá los que no reducen residuos.","segmentos":[{"id":"s1","texto":"Llevá tu bolsa de tela al supermercado."},{"id":"s2","texto":"Comprá todo en porciones individuales para no desperdiciar."},{"id":"s3","texto":"Pedí delivery sin cubiertos descartables."},{"id":"s4","texto":"Comprá más cantidad de lo que está en oferta, aunque no lo vayas a usar."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Reducir es comprar lo que se usa, con el menor envase posible.","por_opcion":{"s2":"Las porciones individuales multiplican los envases; conviene porcionar en casa.","s4":"Si se vence sin usar, se convierte en residuo."}}},{"slug":"residuos-2.s2.p13","orden":13,"grupo":"residuos-2.s2.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Buena parte de la basura se decide al {{0}}; los descartables se usan minutos y duran como residuo {{1}}.","banco":[{"id":"w1","texto":"comprar"},{"id":"w2","texto":"décadas"},{"id":"w3","texto":"tirar"},{"id":"w4","texto":"segundos"},{"id":"w5","texto":"horas"}]},"solucion":{"clave":["w1","w2"],"explicacion":"La idea central de reducir: actuar antes de que el residuo exista."}},{"slug":"residuos-2.s2.p14","orden":14,"grupo":"residuos-2.s2.p14","tipo":"estimar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas bolsas descartables usaría por año una persona que usa 1 por día.","min":50,"max":1000,"paso":5,"unidad":"bolsas","escala":"lineal"},"solucion":{"valor":365,"banda":"lineal","explicacion":"Una por día son 365 por año. Multiplicado por millones de personas, miles de millones de bolsas."}}]},{"slug":"residuos-2.s3","orden":3,"tipo":"leccion","titulo_es":"Reutilizar y reparar","bajada_es":"Retornables, bolsas reutilizables y reparación: cuándo reutilizar compensa y cuánto hay que usar algo para que valga.","minutos":14,"pasos":[{"slug":"residuos-2.s3.p1","orden":1,"grupo":"residuos-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reutilizar es alargar la vida","cuerpo":["Reutilizar es volver a usar un objeto para lo mismo o para otra cosa, sin transformarlo industrialmente: una botella retornable que se lava y se vuelve a llenar, un frasco que guarda legumbres, una mochila que pasa de un hermano a otro.","Reparar es una forma de reutilizar: una silla arreglada, un celular con batería nueva, una campera con cierre cambiado. Cada año de vida extra es un objeto nuevo que no se fabricó."]},"solucion":{}},{"slug":"residuos-2.s3.p2","orden":2,"grupo":"residuos-2.s3.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es reutilizar/reparar o es reciclar?","grupos":[{"id":"g1","nombre":"Reutilizar o reparar"},{"id":"g2","nombre":"Reciclar"}],"items":[{"id":"i1","texto":"Cambiarle la suela a unas zapatillas"},{"id":"i2","texto":"Triturar botellas para hacer fibra"},{"id":"i3","texto":"Usar un frasco de mermelada como vaso"},{"id":"i4","texto":"Fundir latas para hacer aluminio"},{"id":"i5","texto":"Devolver un envase retornable"},{"id":"i6","texto":"Hacer pasta de papel con diarios viejos"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Reutilizar conserva el objeto; reciclar lo destruye para recuperar el material."}},{"slug":"residuos-2.s3.p3","orden":3,"grupo":"residuos-2.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La huella de fabricar","cuerpo":["Un objeto reutilizable suele necesitar más material y energía para fabricarse que uno descartable: una bolsa de tela o un vaso de acero tienen más huella de fabricación que una bolsa o un vaso descartables. Por eso reutilizar compensa solo si se usa muchas veces.","Estudios de ciclo de vida muestran que una bolsa de algodón necesita decenas de usos solo para compensar su huella de carbono frente a una bolsa plástica liviana, y muchos más si se cuentan otros impactos como el agua. La mejor bolsa es la que ya tenés, usada muchas veces."]},"solucion":{}},{"slug":"residuos-2.s3.p4","orden":4,"grupo":"residuos-2.s3.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El punto de equilibrio","planteo":"Fabricar un vaso de acero reutilizable emite lo mismo que fabricar 50 vasos descartables. Lavarlo emite muy poco.","pasos":["Si se usa 10 veces, reemplaza 10 descartables: todavía emite más que ellos.","Si se usa 50 veces, empata.","Si se usa 500 veces, emite alrededor de una décima parte de lo que emitirían 500 descartables."],"resultado":"El reutilizable gana solo si se usa más allá del punto de equilibrio. Comprarlo y olvidarlo en un cajón es peor que no comprarlo."},"solucion":{}},{"slug":"residuos-2.s3.p5","orden":5,"grupo":"residuos-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un objeto reutilizable necesita 50 usos para compensar su fabricación. Si se usa 200 veces, ¿cuántas veces supera ese punto de equilibrio?","unidad":"veces","decimales":1},"solucion":{"valor":4,"tolerancia":0.08,"explicacion":"200 ÷ 50 = 4 veces el punto de equilibrio. A partir de ahí, cada uso es ganancia neta para el ambiente."}},{"slug":"residuos-2.s3.p5.v2","orden":5,"grupo":"residuos-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un objeto reutilizable necesita 30 usos para compensar su fabricación. Si se usa 150 veces, ¿cuántas veces supera ese punto de equilibrio?","unidad":"veces","decimales":1},"solucion":{"valor":5,"tolerancia":0.1,"explicacion":"150 ÷ 30 = 5 veces el punto de equilibrio. A partir de ahí, cada uso es ganancia neta para el ambiente."}},{"slug":"residuos-2.s3.p5.v3","orden":5,"grupo":"residuos-2.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un objeto reutilizable necesita 100 usos para compensar su fabricación. Si se usa 300 veces, ¿cuántas veces supera ese punto de equilibrio?","unidad":"veces","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"300 ÷ 100 = 3 veces el punto de equilibrio. A partir de ahí, cada uso es ganancia neta para el ambiente."}},{"slug":"residuos-2.s3.p6","orden":6,"grupo":"residuos-2.s3.p6","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Comprar una bolsa de tela nueva siempre es mejor para el ambiente que usar bolsas plásticas.","razones":[{"id":"r1","texto":"Porque su fabricación tiene más impacto y hay que compensarlo usándola"},{"id":"r2","texto":"Porque las bolsas de tela no se pueden lavar"},{"id":"r3","texto":"Porque las bolsas plásticas no tienen ningún impacto"}]},"solucion":{"valor":false,"explicacion":"Solo si se usa muchas veces. Fabricar una bolsa de tela tiene más impacto que fabricar una plástica liviana; compensa con el uso repetido.","clave":["r1"]}},{"slug":"residuos-2.s3.p7","orden":7,"grupo":"residuos-2.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Envases retornables","cuerpo":["Un envase retornable de vidrio o de plástico grueso se lava y se vuelve a llenar muchas veces: decenas de ciclos en el caso de algunas botellas de vidrio. Los sistemas de retornables fueron comunes en Argentina con las gaseosas, la leche y la cerveza, y muchas marcas los siguen usando.","Funcionan mejor cuando las distancias son cortas y hay un sistema organizado para devolverlos: si el envase viaja muy lejos, el transporte se come parte del ahorro."]},"solucion":{}},{"slug":"residuos-2.s3.p8","orden":8,"grupo":"residuos-2.s3.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el ciclo de una botella retornable.","items":[{"id":"i1","texto":"Se llena en la planta embotelladora"},{"id":"i2","texto":"Se vende con el producto"},{"id":"i3","texto":"Se devuelve vacía en el comercio"},{"id":"i4","texto":"Vuelve a la planta y se lava"},{"id":"i5","texto":"Se llena de nuevo"},{"id":"i6","texto":"Se funde después de cada uso"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un ciclo sin fundir ni fabricar. Cada vuelta evita una botella nueva."}},{"slug":"residuos-2.s3.p9","orden":9,"grupo":"residuos-2.s3.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que un sistema de retornables funcione bien? Marcá todo lo que ayuda.","opciones":[{"id":"o1","texto":"Distancias cortas entre la planta y los comercios"},{"id":"o2","texto":"Un incentivo para devolver el envase, como un depósito"},{"id":"o3","texto":"Envases resistentes que aguanten muchos lavados"},{"id":"o4","texto":"Muchos comercios donde se puedan devolver"},{"id":"o5","texto":"Envases muy livianos que se rompen con facilidad"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un retornable es un sistema, no solo un envase. Sin logística ni incentivos, los envases no vuelven."}},{"slug":"residuos-2.s3.p10","orden":10,"grupo":"residuos-2.s3.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reparar","cuerpo":["Reparar alarga la vida de los objetos y evita fabricar nuevos. Pero muchos aparatos están diseñados de forma que repararlos es difícil: piezas pegadas, repuestos que no se venden, tornillos especiales. En varios países se discute el \"derecho a reparar\": que los fabricantes vendan repuestos, publiquen manuales y no bloqueen reparaciones.","En muchas ciudades hay talleres de reparación comunitarios donde voluntarios enseñan a arreglar objetos."]},"solucion":{}},{"slug":"residuos-2.s3.p11","orden":11,"grupo":"residuos-2.s3.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué propone el \"derecho a reparar\"?","opciones":[{"id":"o1","texto":"Que los fabricantes faciliten repuestos, manuales y reparaciones"},{"id":"o2","texto":"Que cada persona repare sola cualquier aparato sin ayuda"},{"id":"o3","texto":"Que se prohíba vender aparatos nuevos"},{"id":"o4","texto":"Que los aparatos rotos se reciclen apenas fallan"}]},"solucion":{"clave":["o1"],"explicacion":"Un aparato que se puede reparar puede durar años más. El diseño decide si eso es posible.","por_opcion":{"o3":"No prohíbe vender: pide que reparar sea posible y accesible."}}},{"slug":"residuos-2.s3.p12","orden":12,"grupo":"residuos-2.s3.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas opciones para un celular con la batería gastada, de mejor a peor para el ambiente.","items":[{"id":"i1","texto":"Cambiarle la batería y seguir usándolo"},{"id":"i2","texto":"Venderlo o regalarlo a alguien que lo repare"},{"id":"i3","texto":"Llevarlo a un punto de reciclaje de electrónicos"},{"id":"i4","texto":"Tirarlo con la basura común"}],"extremos":["Mejor","Peor"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Fabricar un celular es la parte más pesada de su huella. Alargar su vida es lo que más ahorra.","valores":{"i1":"evita fabricar un celular nuevo","i2":"otra persona lo sigue usando","i3":"recupera parte de los materiales","i4":"se pierde todo y puede contaminar"}}},{"slug":"residuos-2.s3.p13","orden":13,"grupo":"residuos-2.s3.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta publicidad y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"Nuestro vaso de acero dura años."},{"id":"s2","texto":"Comprá uno de cada color: cada vaso reutilizable ayuda al planeta."},{"id":"s3","texto":"Reemplaza cientos de vasos descartables si lo usás todos los días."},{"id":"s4","texto":"Con solo comprarlo ya estás reduciendo residuos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Lo reutilizable ayuda cuando se usa, no cuando se acumula.","por_opcion":{"s2":"Cada vaso nuevo tiene una huella de fabricación; solo compensa si se usa muchas veces.","s4":"Reduce si se usa en lugar de descartables, no por comprarlo."}}},{"slug":"residuos-2.s3.p14","orden":14,"grupo":"residuos-2.s3.p14","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas veces hay que usar una bolsa de algodón para compensar solo su huella de carbono frente a una bolsa plástica liviana.","min":1,"max":1000,"paso":1,"unidad":"usos","escala":"log"},"solucion":{"valor":50,"banda":"log","explicacion":"Del orden de 50 usos según un estudio de ciclo de vida de la agencia ambiental danesa, y muchos más si se suman otros impactos como el agua. La bolsa que ya tenés, usada mil veces, es la mejor."}},{"slug":"residuos-2.s3.p15","orden":15,"grupo":"residuos-2.s3.p15","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Reparar un aparato casi siempre tiene menos impacto que fabricar uno nuevo.","razones":[{"id":"r1","texto":"Porque la fabricación suele ser la parte más pesada de la huella"},{"id":"r2","texto":"Porque los repuestos no tienen ninguna huella"},{"id":"r3","texto":"Porque los aparatos nuevos no consumen energía"}]},"solucion":{"valor":true,"explicacion":"La mayor parte de la huella de muchos aparatos está en su fabricación. Cambiar una pieza evita fabricar el aparato entero.","clave":["r1"]}},{"slug":"residuos-2.s3.p16","orden":16,"grupo":"residuos-2.s3.p16","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un objeto reutilizable compensa su fabricación recién después de muchos {{0}}; reparar {{1}} la vida del objeto y evita fabricar uno {{2}}.","banco":[{"id":"w1","texto":"usos"},{"id":"w2","texto":"alarga"},{"id":"w3","texto":"nuevo"},{"id":"w4","texto":"lavados"},{"id":"w5","texto":"acorta"},{"id":"w6","texto":"reciclado"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La lógica del punto de equilibrio, en una línea."}}]},{"slug":"residuos-2.s4","orden":4,"tipo":"leccion","titulo_es":"Cómo funciona el reciclaje","bajada_es":"Del punto verde a la fábrica: qué le pasa a cada material, qué dicen los números de los envases y qué se recicla mejor.","minutos":12,"pasos":[{"slug":"residuos-2.s4.p1","orden":1,"grupo":"residuos-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las etapas","cuerpo":["Reciclar es transformar un residuo en materia prima para fabricar algo nuevo. Tiene varias etapas: separación en origen, recolección, clasificación por material (y por tipo, en los plásticos), limpieza, procesamiento (triturar, fundir, hacer pasta) y fabricación del producto nuevo.","Si falla una etapa, el material se pierde. La más frágil suele ser la primera: si el residuo llega sucio o mezclado, muchas veces ya no se puede usar."]},"solucion":{}},{"slug":"residuos-2.s4.p2","orden":2,"grupo":"residuos-2.s4.p2","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas del reciclaje de una botella de plástico.","items":[{"id":"i1","texto":"Se separa en casa, limpia y seca"},{"id":"i2","texto":"Se recolecta"},{"id":"i3","texto":"Se clasifica por tipo de plástico"},{"id":"i4","texto":"Se lava y se tritura en escamas"},{"id":"i5","texto":"Las escamas se usan para fabricar un producto nuevo"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Cada eslabón depende del anterior. El de tu casa es el primero."}},{"slug":"residuos-2.s4.p3","orden":3,"grupo":"residuos-2.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cada material es distinto","cuerpo":["El aluminio y el vidrio se pueden reciclar muchísimas veces sin perder calidad. Reciclar aluminio ahorra alrededor del 95 % de la energía que se necesita para producirlo desde el mineral.","El papel se puede reciclar varias veces, pero sus fibras se acortan en cada vuelta, así que en algún momento hay que sumar fibra nueva. Muchos plásticos pierden calidad al reciclarse y suelen convertirse en productos de menor exigencia: una botella puede volverse fibra textil, y esa fibra, difícilmente una botella otra vez."],"destacado":{"valor":"≈ 95 %","texto":"de la energía se ahorra al fabricar aluminio reciclado en vez de producirlo desde el mineral."}},"solucion":{}},{"slug":"residuos-2.s4.p4","orden":4,"grupo":"residuos-2.s4.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada material con su comportamiento al reciclarse.","izquierda":[{"id":"a1","texto":"Aluminio"},{"id":"a2","texto":"Vidrio"},{"id":"a3","texto":"Papel"},{"id":"a4","texto":"Plástico"}],"derecha":[{"id":"b1","texto":"Se recicla sin perder calidad y ahorra mucha energía"},{"id":"b2","texto":"Se funde y se vuelve vidrio muchas veces"},{"id":"b3","texto":"Sus fibras se acortan en cada vuelta"},{"id":"b4","texto":"Suele perder calidad y bajar de categoría"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"No todo reciclaje es igual. Algunos materiales dan muchas vueltas; otros, pocas."}},{"slug":"residuos-2.s4.p5","orden":5,"grupo":"residuos-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Producir una cantidad de aluminio desde el mineral usa 100 unidades de energía. Si reciclar ahorra el 95 %, ¿cuántas unidades usa hacerlo con aluminio reciclado?","unidad":"unidades","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"Se ahorra el 95 %: se usa el 5 %. 100 × 5 ÷ 100 = 5 unidades. Por eso las latas son de los residuos más valiosos."}},{"slug":"residuos-2.s4.p5.v2","orden":5,"grupo":"residuos-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Producir una cantidad de aluminio desde el mineral usa 200 unidades de energía. Si reciclar ahorra el 95 %, ¿cuántas unidades usa hacerlo con aluminio reciclado?","unidad":"unidades","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"Se ahorra el 95 %: se usa el 5 %. 200 × 5 ÷ 100 = 10 unidades. Por eso las latas son de los residuos más valiosos."}},{"slug":"residuos-2.s4.p5.v3","orden":5,"grupo":"residuos-2.s4.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Producir una cantidad de aluminio desde el mineral usa 150 unidades de energía. Si reciclar ahorra el 95 %, ¿cuántas unidades usa hacerlo con aluminio reciclado?","unidad":"unidades","decimales":1},"solucion":{"valor":7.5,"tolerancia":0.15,"explicacion":"Se ahorra el 95 %: se usa el 5 %. 150 × 5 ÷ 100 = 7.5 unidades. Por eso las latas son de los residuos más valiosos."}},{"slug":"residuos-2.s4.p6","orden":6,"grupo":"residuos-2.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números de los plásticos","cuerpo":["Muchos envases plásticos tienen un triángulo con un número del 1 al 7. No quiere decir que sea reciclable: indica de qué tipo de plástico está hecho. El 1 es PET (botellas de bebidas), el 2 es polietileno de alta densidad (envases de lavandina o shampoo), el 3 es PVC, el 4 polietileno de baja densidad (bolsas y films), el 5 polipropileno (tapas, potes), el 6 poliestireno (incluido el telgopor) y el 7, otros o mezclas.","Los más reciclados en Argentina suelen ser el 1 (PET) y el 2 (PEAD). Otros tienen menos mercado y muchas veces no se recuperan."],"datos":{"tipo":"tabla","titulo":"Códigos de los plásticos","columnas":["Número","Material","Ejemplo"],"filas":[["1","PET","Botellas de bebidas"],["2","PEAD","Envases de lavandina y shampoo"],["3","PVC","Caños, algunos blísteres"],["4","PEBD","Bolsas y films"],["5","PP","Tapas, potes de yogur"],["6","PS","Vasos descartables, telgopor"],["7","Otros","Mezclas y otros plásticos"]]}},"solucion":{}},{"slug":"residuos-2.s4.p7","orden":7,"grupo":"residuos-2.s4.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un envase tiene el triángulo con un número, seguro se recicla.","razones":[{"id":"r1","texto":"Porque el número indica el material, no que haya mercado para reciclarlo"},{"id":"r2","texto":"Porque el triángulo solo se pone en envases de vidrio"},{"id":"r3","texto":"Porque todos los plásticos se reciclan igual"}]},"solucion":{"valor":false,"explicacion":"El número indica el tipo de plástico, no que exista quien lo recicle. Algunos tipos casi no tienen mercado y terminan en el relleno.","clave":["r1"]}},{"slug":"residuos-2.s4.p8","orden":8,"grupo":"residuos-2.s4.p8","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada envase con su número de plástico más probable.","izquierda":[{"id":"a1","texto":"Botella de gaseosa"},{"id":"a2","texto":"Bidón de lavandina"},{"id":"a3","texto":"Tapa de una botella"},{"id":"a4","texto":"Bandeja de telgopor"}],"derecha":[{"id":"b1","texto":"1 (PET)"},{"id":"b2","texto":"2 (PEAD)"},{"id":"b3","texto":"5 (PP)"},{"id":"b4","texto":"6 (PS)"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conocer los códigos ayuda a separar según lo que acepta el punto verde de tu ciudad."}},{"slug":"residuos-2.s4.p9","orden":9,"grupo":"residuos-2.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reciclaje que baja de categoría","cuerpo":["Cuando un material reciclado se usa para un producto de menor exigencia que el original, se habla de infrarreciclaje (downcycling en inglés). Una botella de PET puede convertirse en fibra para una remera o un relleno de almohadón, que después es muy difícil de reciclar otra vez.","Es mejor que enterrar, pero no cierra el círculo: el material termina saliendo del sistema en pocas vueltas."]},"solucion":{}},{"slug":"residuos-2.s4.p10","orden":10,"grupo":"residuos-2.s4.p10","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el recorrido de una botella de PET que baja de categoría.","items":[{"id":"i1","texto":"Botella de gaseosa"},{"id":"i2","texto":"Escamas de PET recicladas"},{"id":"i3","texto":"Fibra para una remera"},{"id":"i4","texto":"Remera usada que casi no se puede reciclar"},{"id":"i5","texto":"Termina como residuo"},{"id":"i6","texto":"Vuelve a ser botella infinitas veces sin pérdida"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Reciclar alarga la vida del material, pero en muchos plásticos no la hace eterna."}},{"slug":"residuos-2.s4.p11","orden":11,"grupo":"residuos-2.s4.p11","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué material suele poder reciclarse muchas veces y cuál pocas?","grupos":[{"id":"g1","nombre":"Muchas veces"},{"id":"g2","nombre":"Pocas veces"}],"items":[{"id":"i1","texto":"Lata de aluminio"},{"id":"i2","texto":"Bandeja de telgopor"},{"id":"i3","texto":"Frasco de vidrio"},{"id":"i4","texto":"Envase multicapa de papas fritas"},{"id":"i5","texto":"Olla de acero"},{"id":"i6","texto":"Film de plástico con restos de comida"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Los metales y el vidrio son los campeones del reciclaje. Los plásticos mezclados y sucios, los que menos vuelven."}},{"slug":"residuos-2.s4.p12","orden":12,"grupo":"residuos-2.s4.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta explicación y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El aluminio se puede reciclar muchas veces."},{"id":"s2","texto":"El número en el triángulo significa que el envase es reciclable en cualquier ciudad."},{"id":"s3","texto":"El papel pierde calidad en cada vuelta."},{"id":"s4","texto":"Una botella de PET siempre vuelve a ser botella."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El reciclaje real depende del material, del estado en que llega y del mercado.","por_opcion":{"s2":"Indica el tipo de plástico; que se recicle depende del mercado y del sistema local.","s4":"Muchas veces se convierte en fibra u otros productos de menor exigencia."}}},{"slug":"residuos-2.s4.p13","orden":13,"grupo":"residuos-2.s4.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué las latas de aluminio son de los residuos más buscados por los recicladores?","opciones":[{"id":"o1","texto":"Porque reciclarlas ahorra mucha energía y no pierden calidad"},{"id":"o2","texto":"Porque son el residuo más pesado de toda la bolsa de basura"},{"id":"o3","texto":"Porque el aluminio se descompone rápido en el relleno"},{"id":"o4","texto":"Porque las latas se pueden compostar junto con los restos de comida"}]},"solucion":{"clave":["o1"],"explicacion":"Un material que ahorra el 95 % de la energía y se recicla sin perder calidad tiene buen precio en el mercado.","por_opcion":{"o3":"El aluminio no se descompone rápido: su valor está en reciclarlo."}}},{"slug":"residuos-2.s4.p14","orden":14,"grupo":"residuos-2.s4.p14","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Las fibras de papel se pueden reciclar infinitas veces sin perder calidad.","razones":[{"id":"r1","texto":"Porque las fibras se acortan en cada reciclaje"},{"id":"r2","texto":"Porque el papel reciclado se vuelve plástico"},{"id":"r3","texto":"Porque el papel no se puede reciclar nunca"}]},"solucion":{"valor":false,"explicacion":"En cada vuelta las fibras se acortan y se debilitan. Después de varias vueltas ya no sirven y hay que sumar fibra nueva.","clave":["r1"]}},{"slug":"residuos-2.s4.p15","orden":15,"grupo":"residuos-2.s4.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Reciclar {{0}} ahorra cerca del 95 % de la energía; el número del triángulo indica el tipo de {{1}}, no que sea {{2}}.","banco":[{"id":"w1","texto":"aluminio"},{"id":"w2","texto":"plástico"},{"id":"w3","texto":"reciclable"},{"id":"w4","texto":"vidrio"},{"id":"w5","texto":"papel"},{"id":"w6","texto":"liviano"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Dos datos que desarman confusiones comunes."}}]},{"slug":"residuos-2.s5","orden":5,"tipo":"leccion","titulo_es":"Por qué reciclar no alcanza","bajada_es":"Solo una fracción del plástico del mundo se recicla. Los límites del reciclaje y el error del \"reciclaje por deseo\".","minutos":12,"pasos":[{"slug":"residuos-2.s5.p1","orden":1,"grupo":"residuos-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los números globales","cuerpo":["A nivel mundial, menos del 10 % de todo el plástico que se produjo se recicló. La mayor parte terminó en rellenos, basurales o el ambiente, o se quemó. En los materiales como el aluminio o el papel las tasas son mucho más altas, pero en los plásticos el reciclaje es la excepción, no la regla.","La producción de plástico, además, sigue creciendo. Aunque se recicle más, si se produce mucho más, el total de residuos igual aumenta."],"destacado":{"valor":"< 10 %","texto":"de todo el plástico producido en el mundo se recicló."}},"solucion":{}},{"slug":"residuos-2.s5.p2","orden":2,"grupo":"residuos-2.s5.p2","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de todo el plástico producido en el mundo se recicló.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":9,"banda":"lineal","explicacion":"Menos del 10 %. El resto se enterró, se quemó o quedó en el ambiente. Por eso el foco está cada vez más en reducir la producción de plásticos innecesarios."}},{"slug":"residuos-2.s5.p3","orden":3,"grupo":"residuos-2.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Reciclar también cuesta","cuerpo":["El reciclaje necesita camiones, plantas, agua para lavar y energía para procesar. Para algunos materiales, el ahorro es enorme (aluminio); para otros, más chico. Y solo funciona si hay alguien que compre el material reciclado: si es más barato fabricar plástico nuevo, el reciclado no se vende y termina en el relleno."]},"solucion":{}},{"slug":"residuos-2.s5.p4","orden":4,"grupo":"residuos-2.s5.p4","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un material separado puede terminar en el relleno igual.","items":[{"id":"i1","texto":"El plástico nuevo es muy barato"},{"id":"i2","texto":"Las fábricas prefieren comprar plástico nuevo"},{"id":"i3","texto":"Nadie compra el plástico reciclado de ese tipo"},{"id":"i4","texto":"El centro verde no puede venderlo"},{"id":"i5","texto":"Termina en el relleno aunque estaba separado"},{"id":"i6","texto":"El plástico separado se destruye solo en el centro verde"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El reciclaje es un mercado. Sin compradores, la separación no alcanza."}},{"slug":"residuos-2.s5.p5","orden":5,"grupo":"residuos-2.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El reciclaje por deseo","cuerpo":["Cuando alguien pone en los reciclables algo que no se recicla \"por las dudas\" —un envase sucio, un vidrio de ventana, un papel plastificado—, cree que ayuda, pero puede contaminar un fardo entero y hacer que se pierda todo. Se lo llama reciclaje por deseo (wishcycling en inglés).","Separar bien es separar lo que realmente se recupera en tu ciudad. Ante la duda, conviene informarse en el punto verde o en la página del municipio."]},"solucion":{}},{"slug":"residuos-2.s5.p6","orden":6,"grupo":"residuos-2.s5.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es el \"reciclaje por deseo\"?","opciones":[{"id":"o1","texto":"Poner en los reciclables cosas que no se reciclan, por las dudas"},{"id":"o2","texto":"Separar solo los materiales que realmente se reciclan"},{"id":"o3","texto":"Desear que haya más plantas de reciclaje"},{"id":"o4","texto":"Reciclar solo los envases que más te gustan"}]},"solucion":{"clave":["o1"],"explicacion":"Con buena intención se puede arruinar un lote entero. Separar bien es separar lo que se recupera.","por_opcion":{"o3":"No es un deseo abstracto: es poner cosas equivocadas en los reciclables."}}},{"slug":"residuos-2.s5.p7","orden":7,"grupo":"residuos-2.s5.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Cuáles de estos residuos suelen arruinar un lote de reciclables? Marcá todos.","opciones":[{"id":"o1","texto":"Una caja de pizza muy engrasada"},{"id":"o2","texto":"Un envase de yogur con restos"},{"id":"o3","texto":"Pañales usados"},{"id":"o4","texto":"Vidrio de ventana mezclado con botellas"},{"id":"o5","texto":"Una botella de PET enjuagada y aplastada"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Grasa, restos de comida y materiales que no corresponden contaminan el lote. La botella limpia es exactamente lo que se busca."}},{"slug":"residuos-2.s5.p8","orden":8,"grupo":"residuos-2.s5.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si no sé si algo se recicla, conviene ponerlo en los reciclables por las dudas.","razones":[{"id":"r1","texto":"Porque un material equivocado puede contaminar todo el lote"},{"id":"r2","texto":"Porque los centros verdes reciclan absolutamente todo"},{"id":"r3","texto":"Porque separar de más nunca tiene consecuencias"}]},"solucion":{"valor":false,"explicacion":"Puede contaminar el lote y hacer que se pierda material que sí se reciclaba. Mejor averiguar qué acepta el sistema de tu ciudad.","clave":["r1"]}},{"slug":"residuos-2.s5.p9","orden":9,"grupo":"residuos-2.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Qué se necesita además","cuerpo":["Para que el reciclaje funcione hacen falta varias cosas a la vez: separación correcta en las casas, recolección diferenciada, plantas y cooperativas con condiciones dignas, mercado para el material reciclado y, sobre todo, productos diseñados desde el principio para ser reciclados o reutilizados.","Y, antes que todo eso, producir menos residuos. Reciclar es una herramienta dentro de la jerarquía, no un permiso para consumir sin límite."]},"solucion":{}},{"slug":"residuos-2.s5.p10","orden":10,"grupo":"residuos-2.s5.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esto depende de cada persona o del sistema?","grupos":[{"id":"g1","nombre":"Cada persona"},{"id":"g2","nombre":"El sistema"}],"items":[{"id":"i1","texto":"Separar limpio y seco"},{"id":"i2","texto":"Recolección diferenciada"},{"id":"i3","texto":"Averiguar qué acepta el punto verde"},{"id":"i4","texto":"Mercado para el material reciclado"},{"id":"i5","texto":"Comprar menos descartables"},{"id":"i6","texto":"Diseño de envases reciclables"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Como viste en el tronco: lo tuyo y lo de todos. El reciclaje necesita las dos columnas."}},{"slug":"residuos-2.s5.p11","orden":11,"grupo":"residuos-2.s5.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país producía 100 mil toneladas de plástico y reciclaba el 9 %. Años después produce 150 mil toneladas y recicla el 15 %. ¿Cuántas mil toneladas NO recicladas tiene ahora?","unidad":"mil toneladas","decimales":1},"solucion":{"valor":127.5,"tolerancia":2.5500000000000003,"explicacion":"Ahora: 150 × 85 ÷ 100 = 127,5 mil t sin reciclar. Antes eran 91. Más reciclaje no compensa si la producción crece más rápido."}},{"slug":"residuos-2.s5.p11.v2","orden":11,"grupo":"residuos-2.s5.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país producía 200 mil toneladas de plástico y reciclaba el 15 %. Años después produce 300 mil toneladas y recicla el 20 %. ¿Cuántas mil toneladas NO recicladas tiene ahora?","unidad":"mil toneladas","decimales":1},"solucion":{"valor":240,"tolerancia":4.8,"explicacion":"Ahora: 300 × 80 ÷ 100 = 240 mil t sin reciclar. Antes eran 170. Más reciclaje no compensa si la producción crece más rápido."}},{"slug":"residuos-2.s5.p11.v3","orden":11,"grupo":"residuos-2.s5.p11","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país producía 150 mil toneladas de plástico y reciclaba el 20 %. Años después produce 250 mil toneladas y recicla el 25 %. ¿Cuántas mil toneladas NO recicladas tiene ahora?","unidad":"mil toneladas","decimales":1},"solucion":{"valor":187.5,"tolerancia":3.75,"explicacion":"Ahora: 250 × 75 ÷ 100 = 187,5 mil t sin reciclar. Antes eran 120. Más reciclaje no compensa si la producción crece más rápido."}},{"slug":"residuos-2.s5.p12","orden":12,"grupo":"residuos-2.s5.p12","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas estrategias contra los residuos plásticos según el escalón de la jerarquía, de más alto a más bajo.","items":[{"id":"i1","texto":"Eliminar envases innecesarios"},{"id":"i2","texto":"Sistemas de envases retornables"},{"id":"i3","texto":"Mejorar la separación y el reciclaje"},{"id":"i4","texto":"Quemar plásticos para generar energía"}],"extremos":["Más alto","Más bajo"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las estrategias más efectivas están arriba. El reciclaje es necesario, pero no es la primera línea.","valores":{"i1":"prevenir","i2":"reutilizar","i3":"reciclar","i4":"recuperar energía"}}},{"slug":"residuos-2.s5.p13","orden":13,"grupo":"residuos-2.s5.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota de opinión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Menos del 10 % del plástico del mundo se recicló."},{"id":"s2","texto":"Por eso separar no sirve para nada."},{"id":"s3","texto":"El reciclaje necesita mercado para el material recuperado."},{"id":"s4","texto":"Si reciclamos más, podemos producir todo el plástico que queramos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Reciclar sí, pero dentro de la escalera: reducir primero.","por_opcion":{"s2":"Separar bien es necesario; lo que no alcanza es solo reciclar sin reducir.","s4":"Si la producción crece más rápido que el reciclaje, los residuos igual aumentan."}}},{"slug":"residuos-2.s5.p14","orden":14,"grupo":"residuos-2.s5.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Menos del {{0}} % del plástico producido se recicló; poner en los reciclables algo que no se recicla es reciclaje por {{1}}.","banco":[{"id":"w1","texto":"10"},{"id":"w2","texto":"deseo"},{"id":"w3","texto":"50"},{"id":"w4","texto":"error"},{"id":"w5","texto":"costumbre"}]},"solucion":{"clave":["w1","w2"],"explicacion":"Dos ideas para entender los límites del reciclaje."}}]},{"slug":"residuos-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: reducir, reutilizar, reciclar","bajada_es":"Jerarquía, reducción, reutilización, reciclaje y sus límites, mezclados.","minutos":8,"pasos":[{"slug":"residuos-2.s6.p1","orden":1,"grupo":"residuos-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Reducir, reutilizar, reciclar». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"residuos-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la cantina del colegio","bajada_es":"La cantina de un colegio genera muchísimos descartables. Con los números, aplicá la jerarquía y armá un plan.","minutos":10,"pasos":[{"slug":"residuos-2.s7.p1","orden":1,"grupo":"residuos-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La cantina","cuerpo":["En un colegio de 600 estudiantes, la cantina vende por día 300 bebidas en botellitas de PET de 500 ml, 200 alfajores envueltos y 150 cafés en vasos descartables con tapa. Hay un solo tacho para todo en el patio.","La dirección quiere reducir los residuos a la mitad este año. Tiene poco presupuesto, pero puede cambiar reglas de la cantina y hacer campañas."]},"solucion":{}},{"slug":"residuos-2.s7.p2","orden":2,"grupo":"residuos-2.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántos envases descartables en total genera la cantina por día (botellas, envoltorios y vasos, sin contar tapas)?","unidad":"envases","decimales":0,"contexto":"300 botellitas, 200 envoltorios y 150 vasos por día."},"solucion":{"valor":650,"tolerancia":13,"explicacion":"300 + 200 + 150 = 650 envases por día. En un año escolar de 180 días, 117.000."}},{"slug":"residuos-2.s7.p3","orden":3,"grupo":"residuos-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el año escolar tiene 180 días, ¿cuántas botellitas de PET se venden por año?","unidad":"botellitas","decimales":0,"contexto":"300 botellitas por día, 180 días de clase."},"solucion":{"valor":54000,"tolerancia":1080,"explicacion":"300 × 180 = 54.000 botellitas por año solo en un colegio."}},{"slug":"residuos-2.s7.p4","orden":4,"grupo":"residuos-2.s7.p4","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas medidas según el escalón de la jerarquía en que están, del más alto al más bajo.","items":[{"id":"i1","texto":"Instalar un bebedero y pedir botellas propias"},{"id":"i2","texto":"Vender café en tazas que se lavan"},{"id":"i3","texto":"Poner tachos separados para PET y cartón"},{"id":"i4","texto":"Seguir con un solo tacho para todo"}],"extremos":["Más alto","Más bajo"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Las medidas de arriba eliminan residuos; las de abajo los manejan. El plan tiene que empezar arriba.","valores":{"i1":"prevenir","i2":"reutilizar","i3":"reciclar","i4":"disponer"}}},{"slug":"residuos-2.s7.p5","orden":5,"grupo":"residuos-2.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el bebedero, el 60 % de los estudiantes deja de comprar botellitas. ¿Cuántas botellitas por día se siguen vendiendo? (antes: 300)","unidad":"botellitas","decimales":0},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"300 × 0,4 = 120 botellitas por día. 180 envases menos cada día, sin reciclar nada."}},{"slug":"residuos-2.s7.p5.v2","orden":5,"grupo":"residuos-2.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el bebedero, el 50 % de los estudiantes deja de comprar botellitas. ¿Cuántas botellitas por día se siguen vendiendo? (antes: 300)","unidad":"botellitas","decimales":0},"solucion":{"valor":150,"tolerancia":3,"explicacion":"300 × 0,5 = 150 botellitas por día. 150 envases menos cada día, sin reciclar nada."}},{"slug":"residuos-2.s7.p5.v3","orden":5,"grupo":"residuos-2.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el bebedero, el 70 % de los estudiantes deja de comprar botellitas. ¿Cuántas botellitas por día se siguen vendiendo? (antes: 300)","unidad":"botellitas","decimales":3},"solucion":{"valor":90.00000000000001,"tolerancia":1.8000000000000003,"explicacion":"300 × 0,3 = 90.00000000000001 botellitas por día. 210 envases menos cada día, sin reciclar nada."}},{"slug":"residuos-2.s7.p6","orden":6,"grupo":"residuos-2.s7.p6","tipo":"opcion","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La cantina propone vasos \"compostables\" en lugar de tazas lavables. ¿Qué tener en cuenta?","opciones":[{"id":"o1","texto":"Solo se compostan si hay un sistema que los reciba"},{"id":"o2","texto":"Son siempre mejores que cualquier taza lavable"},{"id":"o3","texto":"Desaparecen solos en el tacho del patio"},{"id":"o4","texto":"Se pueden reciclar junto con las botellas de PET"}]},"solucion":{"clave":["o1"],"explicacion":"Un descartable \"compostable\" sigue siendo descartable. Sin compostaje organizado, la taza lavable es mejor.","por_opcion":{"o3":"Necesitan condiciones de compostaje; en un relleno se comportan casi como basura común."}}},{"slug":"residuos-2.s7.p7","orden":7,"grupo":"residuos-2.s7.p7","tipo":"clasificar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá estas propuestas del centro de estudiantes.","grupos":[{"id":"g1","nombre":"Reducen residuos de verdad"},{"id":"g2","nombre":"No reducen o empeoran"}],"items":[{"id":"i1","texto":"Descuento a quien trae su taza"},{"id":"i2","texto":"Regalar un vaso reutilizable nuevo cada mes"},{"id":"i3","texto":"Bebederos en cada piso"},{"id":"i4","texto":"Cambiar las botellas por latitas del mismo tamaño"},{"id":"i5","texto":"Alfajores caseros sin envoltorio individual"},{"id":"i6","texto":"Poner más tachos únicos para que no se desborden"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Reducir es que haya menos envases, no cambiar un descartable por otro ni acumular reutilizables sin usar."}},{"slug":"residuos-2.s7.p8","orden":8,"grupo":"residuos-2.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La dirección escribe el plan. Marcá lo que no conviene.","segmen